fn packet_has_object_health(packets: &[ServerPacket], object_id: u32) -> bool {
    packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectHealth { info } if info.object_id == object_id
        )
    })
}

fn packet_has_object_died(packets: &[ServerPacket], object_id: u32) -> bool {
    packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectDied { info } if info.object_id == object_id
        )
    })
}

fn new_character_success_index(packets: &[ServerPacket]) -> i32 {
    match packets.first() {
        Some(ServerPacket::NewCharacterSuccess { char_info }) => char_info.index,
        other => panic!("unexpected new-character packet: {other:?}"),
    }
}

fn attack_until_monster_dies(
    session: &mut SimulationSession,
    object_id: u32,
    max_rounds: usize,
) -> Vec<ServerPacket> {
    for _ in 0..max_rounds {
        let packets = session.attack(object_id);
        if packet_has_object_died(&packets, object_id) {
            return packets;
        }

        let packets = session.tick();
        if packet_has_object_died(&packets, object_id) {
            return packets;
        }
    }

    panic!("monster {object_id} should die within {max_rounds} rounds");
}

fn kill_field_wasp(session: &mut SimulationSession) {
    set_player_position(session, Point { x: 333, y: 267 });
    let _ = attack_until_monster_dies(session, 3002, 5);
}

