#[allow(deprecated)]
fn find_monster_entity_by<F>(session: &SimulationSession, predicate: F) -> Entity
where
    F: Fn(&str, &MonsterAgent, &Point) -> bool,
{
    session
        .app
        .world()
        .iter_entities()
        .find_map(|entity| {
            let name = entity.get::<DisplayName>()?;
            let agent = entity.get::<MonsterAgent>()?;
            let position = entity.get::<Position>()?;
            predicate(name.value.as_str(), agent, &position.0).then_some(entity.id())
        })
        .expect("matching monster should exist")
}

fn spawn_crystal_monster_for_test(
    session: &mut SimulationSession,
    object_id: u32,
    template_name: &str,
    position: Point,
    direction: MirDirection,
    hostile_to_player: bool,
) -> Entity {
    let template =
        crystal_dynamic_monster_template(template_name).expect("crystal monster template");
    let current_tick = runtime_tick(session.app.world());
    let disposition = if hostile_to_player {
        WorldEntityDisposition::Hostile
    } else {
        WorldEntityDisposition::Friendly
    };

    let entity = session
        .app
        .world_mut()
        .spawn((
            WorldObject,
            Monster,
            ObjectId(object_id),
            DisplayName::literal(template.monster_name.clone()),
            Position(position.clone()),
            Facing(direction),
            MonsterAgent {
                image: template.monster_image,
                dead: false,
                patrol_origin: position,
                ai: template.monster_ai,
                disposition,
                hostile_to_player,
                tracking_player: hostile_to_player,
                view_range: i32::from(template.monster_view_range),
                can_wander: super::crystal_respawn_can_wander(template.monster_hp),
                move_interval_ticks: super::crystal_speed_to_ticks(template.monster_move_speed),
                attack_interval_ticks: super::crystal_speed_to_ticks(template.monster_attack_speed),
                next_move_tick: current_tick,
                next_attack_tick: current_tick,
                route: Vec::new(),
                route_index: 0,
                route_waiting: false,
                next_route_tick: current_tick,
            },
            super::initial_monster_ai_state_for_object(
                template.monster_ai,
                current_tick,
                object_id,
            ),
            MonsterVitals {
                hp: template.monster_hp.max(1),
                max_hp: template.monster_hp.max(1),
            },
        ))
        .id();
    if template.monster_ai == 36 {
        session
            .app
            .world_mut()
            .entity_mut(entity)
            .insert(initial_yimoogi_state(current_tick));
    }
    entity
}

