#[test]
fn start_game_packet_trace_matches_bootstrap_order() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    let packets = session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let trace = trace_server_packets(&packets);
    let names = trace
        .iter()
        .take(6)
        .map(|entry| entry.packet)
        .collect::<Vec<_>>();

    assert_eq!(
        names,
        vec![
            "StartGame",
            "Chat",
            "NewItemInfo",
            "NewItemInfo",
            "NewItemInfo",
            "NewItemInfo",
        ]
    );
    assert_eq!(
        trace[0].packet_id,
        mir2_protocol::ServerPacketId::StartGame as i16
    );
    assert_eq!(
        trace[1].packet_id,
        mir2_protocol::ServerPacketId::Chat as i16
    );
    assert_eq!(
        trace[2].packet_id,
        mir2_protocol::ServerPacketId::NewItemInfo as i16
    );
    let map_trace = trace
        .iter()
        .find(|entry| entry.packet == "MapInformation")
        .expect("trace should include map information");
    assert_eq!(
        map_trace.packet_id,
        mir2_protocol::ServerPacketId::MapInformation as i16
    );
}

