#[test]
fn multi_client_shared_store_smoke_keeps_accounts_isolated() {
    let config = SimulationConfig::default();
    let mut alpha = SimulationSession::new(config.clone());
    let mut beta = SimulationSession::new(config.clone());

    let _ = alpha.handle_packet(ClientPacket::NewAccount {
        account_id: "alpha".to_string(),
        password: "alpha-pass".to_string(),
        birth_date_binary: 630_822_816_000_000_000,
        user_name: "Alpha".to_string(),
        secret_question: "q".to_string(),
        secret_answer: "a".to_string(),
        email_address: "alpha@example.test".to_string(),
    });
    let _ = alpha.handle_packet(ClientPacket::Login {
        account_id: "alpha".to_string(),
        password: "alpha-pass".to_string(),
    });
    let alpha_created = alpha.handle_packet(ClientPacket::NewCharacter {
        name: "AlphaBlade".to_string(),
        gender: MirGender::Male,
        class: MirClass::Warrior,
    });
    let alpha_index = new_character_success_index(&alpha_created);
    let _ = alpha.handle_packet(ClientPacket::StartGame {
        character_index: alpha_index,
    });
    set_player_position(&mut alpha, Point { x: 333, y: 267 });
    let _ = alpha.handle_packet(ClientPacket::LogOut);

    let _ = beta.handle_packet(ClientPacket::NewAccount {
        account_id: "beta".to_string(),
        password: "beta-pass".to_string(),
        birth_date_binary: 630_822_816_000_000_000,
        user_name: "Beta".to_string(),
        secret_question: "q".to_string(),
        secret_answer: "a".to_string(),
        email_address: "beta@example.test".to_string(),
    });
    let _ = beta.handle_packet(ClientPacket::Login {
        account_id: "beta".to_string(),
        password: "beta-pass".to_string(),
    });
    let beta_created = beta.handle_packet(ClientPacket::NewCharacter {
        name: "BetaMage".to_string(),
        gender: MirGender::Female,
        class: MirClass::Wizard,
    });
    let beta_index = new_character_success_index(&beta_created);
    let _ = beta.handle_packet(ClientPacket::StartGame {
        character_index: beta_index,
    });
    set_player_position(&mut beta, Point { x: 334, y: 267 });
    let _ = beta.handle_packet(ClientPacket::LogOut);

    let mut alpha_reload = SimulationSession::new(config.clone());
    let alpha_login = alpha_reload.handle_packet(ClientPacket::Login {
        account_id: "alpha".to_string(),
        password: "alpha-pass".to_string(),
    });
    let alpha_names = match &alpha_login[0] {
        ServerPacket::LoginSuccess { characters } => characters
            .iter()
            .map(|character| character.name.as_str())
            .collect::<Vec<_>>(),
        other => panic!("unexpected alpha login packet: {other:?}"),
    };
    assert!(alpha_names.contains(&"AlphaBlade"));
    assert!(!alpha_names.contains(&"BetaMage"));
    let _ = alpha_reload.handle_packet(ClientPacket::StartGame {
        character_index: alpha_index,
    });
    let alpha_player = alpha_reload
        .world_snapshot()
        .entities
        .into_iter()
        .find(|entity| entity.kind == crate::WorldEntityKind::SelfPlayer)
        .expect("alpha player should restore");
    assert_eq!((alpha_player.x, alpha_player.y), (333, 267));

    let mut beta_reload = SimulationSession::new(config);
    let beta_login = beta_reload.handle_packet(ClientPacket::Login {
        account_id: "beta".to_string(),
        password: "beta-pass".to_string(),
    });
    let beta_names = match &beta_login[0] {
        ServerPacket::LoginSuccess { characters } => characters
            .iter()
            .map(|character| character.name.as_str())
            .collect::<Vec<_>>(),
        other => panic!("unexpected beta login packet: {other:?}"),
    };
    assert!(beta_names.contains(&"BetaMage"));
    assert!(!beta_names.contains(&"AlphaBlade"));
    let _ = beta_reload.handle_packet(ClientPacket::StartGame {
        character_index: beta_index,
    });
    let beta_player = beta_reload
        .world_snapshot()
        .entities
        .into_iter()
        .find(|entity| entity.kind == crate::WorldEntityKind::SelfPlayer)
        .expect("beta player should restore");
    assert_eq!((beta_player.x, beta_player.y), (334, 267));
}

#[test]
fn long_running_tick_soak_preserves_player_state_without_panic() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    let _ = session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    for tick in 0..1_200 {
        if tick % 120 == 0 {
            let _ = session.handle_packet(ClientPacket::KeepAlive { time: tick });
        }
        let _ = session.tick();
    }

    let snapshot = session.world_snapshot();
    assert_eq!(snapshot.tick, 1_200);
    assert!(snapshot.player_object_id.is_some());
    assert!(snapshot.player_hp.unwrap_or_default() > 0);
    assert!(snapshot
        .entities
        .iter()
        .any(|entity| { entity.kind == crate::WorldEntityKind::SelfPlayer && !entity.dead }));
}

#[test]
fn save_reload_under_load_restores_multiple_clients() {
    let temp_dir = unique_runtime_temp_dir("load-reload");
    let store_path = temp_dir.join("accounts.json");
    let config = SimulationConfig::default().with_account_store_path(store_path.clone());
    let mut alpha = SimulationSession::new(config.clone());
    let mut beta = SimulationSession::new(config.clone());

    let _ = alpha.handle_packet(ClientPacket::NewAccount {
        account_id: "load-alpha".to_string(),
        password: "alpha-pass".to_string(),
        birth_date_binary: 630_822_816_000_000_000,
        user_name: "Load Alpha".to_string(),
        secret_question: "q".to_string(),
        secret_answer: "a".to_string(),
        email_address: "alpha@example.test".to_string(),
    });
    let _ = alpha.handle_packet(ClientPacket::Login {
        account_id: "load-alpha".to_string(),
        password: "alpha-pass".to_string(),
    });
    let alpha_created = alpha.handle_packet(ClientPacket::NewCharacter {
        name: "LoadAlpha".to_string(),
        gender: MirGender::Male,
        class: MirClass::Warrior,
    });
    let alpha_index = new_character_success_index(&alpha_created);
    let _ = alpha.handle_packet(ClientPacket::StartGame {
        character_index: alpha_index,
    });

    let _ = beta.handle_packet(ClientPacket::NewAccount {
        account_id: "load-beta".to_string(),
        password: "beta-pass".to_string(),
        birth_date_binary: 630_822_816_000_000_000,
        user_name: "Load Beta".to_string(),
        secret_question: "q".to_string(),
        secret_answer: "a".to_string(),
        email_address: "beta@example.test".to_string(),
    });
    let _ = beta.handle_packet(ClientPacket::Login {
        account_id: "load-beta".to_string(),
        password: "beta-pass".to_string(),
    });
    let beta_created = beta.handle_packet(ClientPacket::NewCharacter {
        name: "LoadBeta".to_string(),
        gender: MirGender::Female,
        class: MirClass::Wizard,
    });
    let beta_index = new_character_success_index(&beta_created);
    let _ = beta.handle_packet(ClientPacket::StartGame {
        character_index: beta_index,
    });

    for tick in 0..180 {
        if tick % 30 == 0 {
            let _ = alpha.handle_packet(ClientPacket::KeepAlive { time: tick });
            let _ = beta.handle_packet(ClientPacket::KeepAlive { time: tick });
        }
        let _ = alpha.tick();
        let _ = beta.tick();
    }
    set_player_position(&mut alpha, Point { x: 337, y: 268 });
    set_player_position(&mut beta, Point { x: 338, y: 268 });
    alpha.save_active_character();
    beta.save_active_character();
    config
        .backup_account_store(temp_dir.join("accounts.load.backup.json"))
        .expect("account store backup should succeed under load");

    let reloaded = SimulationConfig::default().with_account_store_path(store_path);
    let mut alpha_reload = SimulationSession::new(reloaded.clone());
    let _ = alpha_reload.handle_packet(ClientPacket::Login {
        account_id: "load-alpha".to_string(),
        password: "alpha-pass".to_string(),
    });
    let _ = alpha_reload.handle_packet(ClientPacket::StartGame {
        character_index: alpha_index,
    });
    let alpha_player = alpha_reload
        .world_snapshot()
        .entities
        .into_iter()
        .find(|entity| entity.kind == crate::WorldEntityKind::SelfPlayer)
        .expect("alpha should reload");
    assert_eq!((alpha_player.x, alpha_player.y), (337, 268));

    let mut beta_reload = SimulationSession::new(reloaded);
    let _ = beta_reload.handle_packet(ClientPacket::Login {
        account_id: "load-beta".to_string(),
        password: "beta-pass".to_string(),
    });
    let _ = beta_reload.handle_packet(ClientPacket::StartGame {
        character_index: beta_index,
    });
    let beta_player = beta_reload
        .world_snapshot()
        .entities
        .into_iter()
        .find(|entity| entity.kind == crate::WorldEntityKind::SelfPlayer)
        .expect("beta should reload");
    assert_eq!((beta_player.x, beta_player.y), (338, 268));

    let _ = std::fs::remove_dir_all(temp_dir);
}

#[test]
fn long_running_tick_soak_keeps_entity_count_bounded() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    let _ = session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let baseline = runtime_entity_count(&session);
    let mut peak = baseline;

    for tick in 0..1_200 {
        if tick % 120 == 0 {
            let _ = session.handle_packet(ClientPacket::KeepAlive { time: tick });
        }
        let _ = session.tick();
        peak = peak.max(runtime_entity_count(&session));
    }

    assert!(
        peak <= baseline + 16,
        "runtime entity count grew from {baseline} to {peak}"
    );
}

