#[test]
fn walk_updates_self_location() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let packets = session.handle_packet(ClientPacket::Walk {
        direction: MirDirection::Right,
    });

    match &packets[0] {
        ServerPacket::UserLocation { location } => {
            assert_eq!(location.position.x, 331);
            assert_eq!(location.position.y, 270);
            assert_eq!(location.direction, MirDirection::Right);
        }
        other => panic!("unexpected packet: {other:?}"),
    }
}

#[test]
fn combat_packet_trace_orders_attack_before_delayed_health() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    let _ = session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_player_position(&mut session, Point { x: 333, y: 267 });
    sync_visible_objects(&mut session);

    let launch_packets = session.attack(3002);
    let launch_names = trace_server_packets(&launch_packets)
        .into_iter()
        .map(|entry| entry.packet)
        .collect::<Vec<_>>();
    assert!(launch_names.contains(&"ObjectAttack"));
    assert!(!launch_names.contains(&"ObjectHealth"));

    let hit_packets = session.tick();
    let hit_names = trace_server_packets(&hit_packets)
        .into_iter()
        .map(|entry| entry.packet)
        .collect::<Vec<_>>();
    let struck_index = hit_names
        .iter()
        .position(|packet| *packet == "ObjectStruck")
        .expect("delayed hit should emit ObjectStruck");
    let health_index = hit_names
        .iter()
        .position(|packet| *packet == "ObjectHealth")
        .expect("delayed hit should emit ObjectHealth");
    assert!(struck_index < health_index);
}

