#[test]
fn crystal_manifest_movements_surface_as_runtime_transfers() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    let _ = session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let transfer = session
        .world_snapshot()
        .map_transfers
        .into_iter()
        .find(|transfer| {
            transfer.map_file_name == "0"
                && transfer.to_map_file_name == "0122"
                && transfer.bounds.min_x == 347
                && transfer.bounds.min_y == 188
                && transfer.to_position == (Point { x: 13, y: 40 })
        })
        .expect("Bichon to Palace movement should be imported");

    set_player_position(
        &mut session,
        Point {
            x: transfer.bounds.min_x,
            y: transfer.bounds.min_y,
        },
    );
    let packets = session.transfer_map(&transfer.key);

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::MapInformation { info }
            if info.file_name == "0122" && info.title == "Palace"
    )));
    assert_eq!(player_position(&session), Point { x: 13, y: 40 });
}

#[test]
fn spread_slots_choose_walkable_tiles_inside_square_range() {
    let config = SimulationConfig::default();
    let origin = Point { x: 327, y: 265 };
    let positions = spawn_positions_for_rule(&config, &origin, 1, 4, 0);

    assert_eq!(positions.len(), 4);
    assert!(positions.iter().all(|position| {
        (position.x - origin.x).abs() <= 1
            && (position.y - origin.y).abs() <= 1
            && is_static_spawnable_point(&config, position)
            && *position != origin
    }));
}

#[test]
fn crystal_starter_region_source_builds_imported_spawn_rules() {
    let mut config = SimulationConfig::default();
    config.monster_spawn_source = MonsterSpawnSource::CrystalStarterRegion;

    let table = build_spawn_table(&config);
    let total_slots = table
        .rules
        .iter()
        .map(|rule| rule.slots.len())
        .sum::<usize>();

    assert!(table.rules.iter().any(|rule| rule.name == "Hen"));
    assert!(table.rules.iter().any(|rule| rule.name == "Royal_Guard"));
    assert!(table.rules.iter().any(|rule| rule.name == "Royal_Archer"));
    assert!(total_slots >= 17);
}

#[test]
fn crystal_current_map_spawn_table_uses_representative_map_rosters() {
    let config = SimulationConfig::default();

    let hf1 = build_crystal_current_map_spawn_table(&config, "HF1");
    assert!(hf1
        .rules
        .iter()
        .any(|rule| rule.name == "HellKnight1" && rule.ai == 97 && rule.slots.len() == 4));
    assert!(hf1
        .rules
        .iter()
        .any(|rule| rule.name == "HellBomb1" && rule.ai == 99 && rule.slots.len() == 4));

    let penal_cavern = build_crystal_current_map_spawn_table(&config, "D1801");
    assert!(penal_cavern
        .rules
        .iter()
        .any(|rule| rule.name == "PKSpirit" && rule.ai == 38 && rule.slots.len() == 4));

    let hellfire_king = build_crystal_current_map_spawn_table(&config, "HKR");
    assert!(hellfire_king
        .rules
        .iter()
        .any(|rule| rule.name == "HellLord" && rule.ai == 98 && rule.slots.len() == 1));
}

#[test]
fn crystal_respawn_schedule_uses_minute_window_semantics() {
    let without_random = respawn_tick_for_schedule(
        &MonsterRespawnSchedule::CrystalMinutes {
            delay_minutes: 5,
            random_delay_minutes: 0,
        },
        10,
        0,
        0,
    );
    assert_eq!(without_random, 310);

    let with_random = respawn_tick_for_schedule(
        &MonsterRespawnSchedule::CrystalMinutes {
            delay_minutes: 5,
            random_delay_minutes: 2,
        },
        42,
        3,
        1,
    );
    let delta = with_random - 42;
    assert!((180..=360).contains(&delta));
    assert_eq!(delta % 60, 0);
}

#[test]
fn crystal_route_guard_moves_along_patrol() {
    let mut config = SimulationConfig::default();
    config.monster_spawn_source = MonsterSpawnSource::CrystalStarterRegion;
    let mut session = SimulationSession::new(config);
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let before = session
        .world_snapshot()
        .entities
        .into_iter()
        .find(|entity| entity.name == "Royal_Guard" && entity.x == 319 && entity.y == 270)
        .expect("route guard should spawn inside starter region");

    let _ = session.tick();

    let after = session
        .world_snapshot()
        .entities
        .into_iter()
        .find(|entity| entity.object_id == before.object_id)
        .expect("route guard should still exist");

    assert_ne!((after.x, after.y), (before.x, before.y));
}

