#[test]
fn crystal_guard_attack_uses_target_back_packet_shape() {
    let mut config = SimulationConfig::default();
    config.monster_spawn_source = MonsterSpawnSource::CrystalStarterRegion;
    let mut session = SimulationSession::new(config);
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let guard_entity = find_monster_entity_by(&session, |name, agent, position| {
        name == "Royal_Guard" && agent.ai == 6 && position.x == 319 && position.y == 270
    });
    let guard_position = Point { x: 900, y: 900 };
    let guard_object_id =
        entity_object_id(session.app.world(), guard_entity).expect("guard object id");
    let current_tick = runtime_tick(session.app.world());

    set_entity_position(&mut session, guard_entity, guard_position.clone());
    session
        .app
        .world_mut()
        .entity_mut(guard_entity)
        .insert(Facing(MirDirection::Left));

    let target_entity = session
        .app
        .world_mut()
        .spawn((
            ObjectId(98_771_u32),
            DisplayName::literal("Guard Packet Test"),
            Position(Point {
                x: guard_position.x + 1,
                y: guard_position.y,
            }),
            Facing(MirDirection::Up),
            Monster,
            MonsterVitals { hp: 12, max_hp: 12 },
            MonsterAgent {
                image: 43,
                dead: false,
                patrol_origin: guard_position.clone(),
                ai: 0,
                disposition: WorldEntityDisposition::Hostile,
                hostile_to_player: true,
                tracking_player: false,
                view_range: 7,
                can_wander: true,
                move_interval_ticks: 1,
                attack_interval_ticks: 1,
                next_move_tick: current_tick,
                next_attack_tick: current_tick,
                route: Vec::new(),
                route_index: 0,
                route_waiting: false,
                next_route_tick: current_tick,
            },
        ))
        .id();

    set_player_position(&mut session, guard_position.clone());

    let packets = session.tick();

    let attack_index = packets
        .iter()
        .position(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info }
                    if info.object_id == guard_object_id
                        && info.location == Point { x: 901, y: 901 }
                        && info.direction == MirDirection::Up
            )
        })
        .expect("guard attack should use target back and attack direction");
    let turn_index = packets
        .iter()
        .position(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectTurn { movement }
                    if movement.object_id == guard_object_id
                        && movement.position == guard_position
                        && movement.direction == MirDirection::Left
            )
        })
        .expect("guard attack should preserve current facing via object turn");

    assert!(attack_index < turn_index);
    assert!(
        !session
            .app
            .world()
            .entity(target_entity)
            .get::<MonsterAgent>()
            .expect("target agent")
            .dead
    );

    let hit_packets = session.tick();
    assert!(hit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectStruck { info } if info.object_id == 98_771_u32
    )));
    assert!(
        session
            .app
            .world()
            .entity(target_entity)
            .get::<MonsterAgent>()
            .expect("target agent")
            .dead
    );
}

