#[test]
fn crystal_guards_ignore_hens_even_when_adjacent() {
    let mut config = SimulationConfig::default();
    config.monster_spawn_source = MonsterSpawnSource::CrystalStarterRegion;
    let mut session = SimulationSession::new(config);
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let guard_entity = find_monster_entity_by(&session, |name, agent, position| {
        name == "Royal_Guard" && agent.ai == 6 && position.x == 319 && position.y == 270
    });
    let hen_entity =
        find_monster_entity_by(&session, |name, agent, _| name == "Hen" && agent.ai == 1);

    let guard_position =
        entity_position(session.app.world(), guard_entity).expect("guard position");
    let hen_object_id = entity_object_id(session.app.world(), hen_entity).expect("hen object id");
    let hen_hp_before = session
        .app
        .world()
        .entity(hen_entity)
        .get::<MonsterVitals>()
        .expect("hen vitals")
        .hp;

    set_player_position(&mut session, guard_position.clone());
    set_entity_position(
        &mut session,
        hen_entity,
        Point {
            x: guard_position.x + 1,
            y: guard_position.y,
        },
    );

    let packets = session.tick();

    assert!(!packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectDied { info } if info.object_id == hen_object_id
    )));
    let hen_vitals = session
        .app
        .world()
        .entity(hen_entity)
        .get::<MonsterVitals>()
        .expect("hen vitals");
    let hen_agent = session
        .app
        .world()
        .entity(hen_entity)
        .get::<MonsterAgent>()
        .expect("hen agent");
    assert_eq!(hen_vitals.hp, hen_hp_before);
    assert!(!hen_agent.dead);
}

#[test]
fn player_attack_locks_monster_target_and_uses_runtime_counterattack() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let player_object_id = entity_object_id(session.app.world(), player).expect("player object id");
    let player_origin = player_position(&session);
    let monster_object_id = 98_766_u32;
    let current_tick = runtime_tick(session.app.world());

    set_player_position(&mut session, player_origin.clone());
    let monster_entity = session
        .app
        .world_mut()
        .spawn((
            ObjectId(monster_object_id),
            DisplayName::literal("Aggro Test Wasp"),
            Position(Point {
                x: player_origin.x + 1,
                y: player_origin.y,
            }),
            Facing(MirDirection::Left),
            Monster,
            MonsterVitals {
                hp: 100,
                max_hp: 100,
            },
            MonsterAgent {
                image: 43,
                dead: false,
                patrol_origin: player_origin.clone(),
                ai: 0,
                disposition: WorldEntityDisposition::Hostile,
                hostile_to_player: true,
                tracking_player: false,
                view_range: 7,
                can_wander: true,
                move_interval_ticks: 1,
                attack_interval_ticks: 1,
                next_move_tick: current_tick,
                next_attack_tick: current_tick,
                route: Vec::new(),
                route_index: 0,
                route_waiting: false,
                next_route_tick: current_tick,
            },
        ))
        .id();
    let before_hp = session.world_snapshot().player_hp.expect("player hp");

    let packets = session.attack(monster_object_id);

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectAttack { info } if info.object_id == player_object_id
    )));

    let monster_agent = session
        .app
        .world()
        .entity(monster_entity)
        .get::<MonsterAgent>()
        .expect("monster agent");
    assert!(monster_agent.tracking_player);
    assert!(!monster_agent.dead);
    let after_hp = session.world_snapshot().player_hp.expect("player hp");
    assert_eq!(after_hp, before_hp);

    let counter_packets = session.tick();
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectAttack { info } if info.object_id == monster_object_id
    )));
    assert!(counter_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Struck { info } if info.attacker_id == monster_object_id
    )));
    let after_counter_hp = session.world_snapshot().player_hp.expect("player hp");
    assert!(after_counter_hp < before_hp);
}

