#[test]
fn player_attack_delays_health_change_until_followup_tick() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_player_position(&mut session, Point { x: 333, y: 267 });
    let before = session
        .world_snapshot()
        .entities
        .into_iter()
        .find(|entity| entity.object_id == 3002)
        .and_then(|entity| entity.hp)
        .expect("monster hp");

    let attack_packets = session.attack(3002);
    let after_attack = session
        .world_snapshot()
        .entities
        .into_iter()
        .find(|entity| entity.object_id == 3002)
        .and_then(|entity| entity.hp)
        .expect("monster hp");

    assert!(!attack_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectHealth { info } if info.object_id == 3002
    )));
    assert_eq!(after_attack, before);

    let hit_packets = session.tick();
    let after_hit = session
        .world_snapshot()
        .entities
        .into_iter()
        .find(|entity| entity.object_id == 3002)
        .and_then(|entity| entity.hp)
        .expect("monster hp");

    assert!(hit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectHealth { info } if info.object_id == 3002
    )));
    assert!(after_hit < before);
}

