#[test]
fn cannibal_plant_hidden_state_blocks_attack_until_revealed() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let monster_object_id = 98_881_u32;
    let current_tick = runtime_tick(session.app.world());

    set_player_position(&mut session, player_origin.clone());
    let _monster_entity = session
        .app
        .world_mut()
        .spawn((
            ObjectId(monster_object_id),
            DisplayName::literal("Cannibal Plant Test"),
            Position(Point {
                x: player_origin.x + 4,
                y: player_origin.y,
            }),
            Facing(MirDirection::Left),
            Monster,
            MonsterVitals { hp: 50, max_hp: 50 },
            MonsterAgent {
                image: 43,
                dead: false,
                patrol_origin: player_origin.clone(),
                ai: 5,
                disposition: WorldEntityDisposition::Hostile,
                hostile_to_player: true,
                tracking_player: false,
                view_range: 7,
                can_wander: true,
                move_interval_ticks: 1,
                attack_interval_ticks: 1,
                next_move_tick: current_tick,
                next_attack_tick: current_tick,
                route: Vec::new(),
                route_index: 0,
                route_waiting: false,
                next_route_tick: current_tick,
            },
            MonsterAiState {
                hidden: true,
                extra: false,
                extra_byte: 0,
                mode: false,
                next_state_tick: 0,
            },
        ))
        .id();
    sync_visible_objects(&mut session);

    assert!(!session.visible_objects.contains(&monster_object_id));
    let attack_packets = session.attack(monster_object_id);
    assert!(!attack_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::Chat { .. })));
    assert!(!attack_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectAttack { .. } | ServerPacket::ObjectRangeAttack { .. }
    )));

    set_player_position(
        &mut session,
        Point {
            x: player_origin.x + 2,
            y: player_origin.y,
        },
    );
    let reveal_packets = session.tick();

    let spawn_index = reveal_packets
        .iter()
        .position(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectMonster { info } if info.object_id == monster_object_id
            )
        })
        .expect("revealed plant should spawn");
    let show_index = reveal_packets
        .iter()
        .position(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectShow { object_id } if *object_id == monster_object_id
            )
        })
        .expect("revealed plant should emit object show");
    assert!(spawn_index < show_index);
}

