#[test]
fn runaway_deer_flees_from_player_without_attacking() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let (player_origin, deer_position, expected_step) = (240..460)
        .find_map(|y| {
            (240..460).find_map(|x| {
                let player_position = Point { x, y };
                let deer_position = Point { x: x + 1, y };
                let expected_step = Point { x: x + 2, y };
                (can_occupy(session.app.world(), player_position.clone(), Some(player))
                    && can_occupy(session.app.world(), deer_position.clone(), None)
                    && can_occupy(session.app.world(), expected_step.clone(), None))
                .then_some((player_position, deer_position, expected_step))
            })
        })
        .expect("test should find an open runaway deer lane");
    let deer_object_id = 98_915_u32;
    set_player_position(&mut session, player_origin);
    let deer = spawn_crystal_monster_for_test(
        &mut session,
        deer_object_id,
        "Deer",
        deer_position,
        MirDirection::Left,
        false,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(deer);
        let mut ai_state = entry.get_mut::<MonsterAiState>().expect("deer ai state");
        ai_state.mode = true;
        let mut agent = entry.get_mut::<MonsterAgent>().expect("deer agent");
        agent.tracking_player = false;
        agent.move_interval_ticks = 1;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let packets = session.tick();
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectWalk { movement }
            if movement.object_id == deer_object_id
                && movement.position == expected_step
                && movement.direction == MirDirection::Right
    )));
    assert!(!packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectAttack { info } if info.object_id == deer_object_id
    )));
    assert!(
        session
            .app
            .world()
            .entity(deer)
            .get::<MonsterAgent>()
            .expect("deer agent")
            .tracking_player
    );
}

#[test]
fn hen_is_passive_and_requires_two_skin_passes_then_transfer() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let (player_origin, hen_position) = (240..460)
        .find_map(|y| {
            (240..460).find_map(|x| {
                let player = Point { x, y };
                let hen = Point { x: x + 1, y };
                (can_occupy(session.app.world(), player.clone(), None)
                    && can_occupy(session.app.world(), hen.clone(), None))
                .then_some((player, hen))
            })
        })
        .expect("test should find an occupiable harvest line");
    let hen_object_id = 98_913_u32;
    set_player_position(&mut session, player_origin);
    assert!(!super::monster_targets_players(1));
    assert_eq!(
        super::initial_harvest_monster_state(1)
            .expect("hen harvest state")
            .remaining_skin_count,
        super::HARVEST_MONSTER_SKIN_COUNT
    );

    let hen = spawn_crystal_monster_for_test(
        &mut session,
        hen_object_id,
        "Hen",
        hen_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(hen);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("hen agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.next_attack_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    for _ in 0..2 {
        let packets = session.tick();
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info } if info.object_id == hen_object_id
            )
        }));
    }

    let death_tick = runtime_tick(session.app.world());
    let mut death_packets = Vec::new();
    assert!(super::damage_monster_entity(
        session.app.world_mut(),
        hen,
        i32::MAX,
        death_tick,
        &mut death_packets,
    ));
    assert!(packet_has_object_died(&death_packets, hen_object_id));
    assert_eq!(
        entity_position(session.app.world(), hen).expect("hen position"),
        hen_position
    );

    let mut expected_chicken_dura = None;
    for harvest_index in 1..=super::HARVEST_MONSTER_SKIN_COUNT {
        let generated_chicken_dura = super::crystal_drop_item_current_durability(
            4000,
            runtime_tick(session.app.world()),
            hen_object_id,
            0,
        );
        let packets = session.handle_packet(ClientPacket::Harvest {
            direction: MirDirection::Right,
        });
        let harvested = packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectHarvested { movement }
                    if movement.object_id == hen_object_id
            )
        });
        assert_eq!(
            harvested, false,
            "harvest {harvest_index}, packets {packets:?}"
        );
        if harvest_index == super::HARVEST_MONSTER_SKIN_COUNT {
            expected_chicken_dura = Some(generated_chicken_dura);
            let state = session
                .app
                .world()
                .entity(hen)
                .get::<super::HarvestMonsterState>()
                .copied()
                .expect("hen harvest state after final skin pass");
            assert_eq!(state.remaining_skin_count, 0);
            assert!(state.drops_ready);
            assert!(!state.harvested);
            assert!(!packets
                .iter()
                .any(|packet| matches!(packet, ServerPacket::GainedItem { .. })));
        }
    }

    let transfer_packets = session.handle_packet(ClientPacket::Harvest {
        direction: MirDirection::Right,
    });
    assert!(transfer_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectHarvested { movement }
                if movement.object_id == hen_object_id
        )
    }));
    assert!(transfer_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::GainedItem { item }
            if item.item_index == 850
                && item.count == 1
                && item.current_dura == expected_chicken_dura.expect("generated dura")
                && item.max_dura == 4000
                && item.identified
    )));
    assert!(session
        .world_snapshot()
        .inventory_items
        .iter()
        .any(|item| item.key == "crystal-item-850" && item.name == "Chicken"));
}

#[test]
fn harvest_keeps_pending_drops_when_bag_is_full_and_transfers_later() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let (player_origin, hen_position) = (240..460)
        .find_map(|y| {
            (240..460).find_map(|x| {
                let player = Point { x, y };
                let hen = Point { x: x + 1, y };
                (can_occupy(session.app.world(), player.clone(), None)
                    && can_occupy(session.app.world(), hen.clone(), None))
                .then_some((player, hen))
            })
        })
        .expect("test should find an occupiable harvest line");
    let hen_object_id = 98_919_u32;
    set_player_position(&mut session, player_origin);
    let hen = spawn_crystal_monster_for_test(
        &mut session,
        hen_object_id,
        "Hen",
        hen_position.clone(),
        MirDirection::Left,
        true,
    );
    sync_visible_objects(&mut session);

    let death_tick = runtime_tick(session.app.world());
    let mut death_packets = Vec::new();
    assert!(super::damage_monster_entity(
        session.app.world_mut(),
        hen,
        i32::MAX,
        death_tick,
        &mut death_packets,
    ));
    assert!(packet_has_object_died(&death_packets, hen_object_id));

    for _ in 0..super::HARVEST_MONSTER_SKIN_COUNT {
        let packets = session.handle_packet(ClientPacket::Harvest {
            direction: MirDirection::Right,
        });
        assert!(!packets
            .iter()
            .any(|packet| matches!(packet, ServerPacket::ObjectHarvested { .. })));
    }
    assert_eq!(
        session
            .app
            .world()
            .entity(hen)
            .get::<super::PendingHarvestDrops>()
            .expect("pending hen drops")
            .drops
            .len(),
        1
    );

    fill_all_bag_slots(&mut session);
    let blocked_packets = session.handle_packet(ClientPacket::Harvest {
        direction: MirDirection::Right,
    });
    assert!(blocked_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            chat_type: ChatType::System,
            message
        } if message
            == &super::localized_text_or_fallback(
                super::LanguageCode::English,
                "server.YouCannotCarryAnymore",
                "server.YouCannotCarryAnymore",
            )
    )));
    assert!(!blocked_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::ObjectHarvested { .. })));
    assert!(session
        .app
        .world()
        .entity(hen)
        .get::<super::PendingHarvestDrops>()
        .is_some());

    session
        .app
        .world_mut()
        .resource_mut::<InventoryResource>()
        .inventory_items
        .pop();
    let transfer_packets = session.handle_packet(ClientPacket::Harvest {
        direction: MirDirection::Right,
    });

    assert!(transfer_packets.iter().any(
        |packet| matches!(packet, ServerPacket::GainedItem { item } if item.item_index == 850)
    ));
    assert!(transfer_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectHarvested { movement }
                if movement.object_id == hen_object_id
        )
    }));
    assert!(session
        .app
        .world()
        .entity(hen)
        .get::<super::PendingHarvestDrops>()
        .is_none());
}

#[test]
fn harvest_skips_owner_blocked_corpse_and_harvests_next_candidate() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let player_origin = Point { x: 330, y: 270 };
    set_player_position(&mut session, player_origin.clone());

    let blocked = spawn_crystal_monster_for_test(
        &mut session,
        98_940,
        "Hen",
        Point { x: 331, y: 270 },
        MirDirection::Left,
        true,
    );
    let candidate = spawn_crystal_monster_for_test(
        &mut session,
        98_941,
        "Hen",
        Point { x: 331, y: 271 },
        MirDirection::Left,
        true,
    );
    for (entity, ownership) in [(blocked, Some(9001_u32)), (candidate, None)] {
        let mut entry = session.app.world_mut().entity_mut(entity);
        entry.insert(MonsterVitals { hp: 0, max_hp: 1 });
        {
            let mut agent = entry.get_mut::<MonsterAgent>().expect("hen agent");
            agent.dead = true;
        }
        if let Some(owner_object_id) = ownership {
            entry.insert(super::HarvestOwnership { owner_object_id });
        }
    }

    let packets = session.handle_packet(ClientPacket::Harvest {
        direction: MirDirection::Right,
    });

    assert!(!packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message.contains("carcasses")
    )));
    assert_eq!(
        session
            .app
            .world()
            .entity(blocked)
            .get::<super::HarvestMonsterState>()
            .map(|state| state.remaining_skin_count)
            .unwrap_or(super::HARVEST_MONSTER_SKIN_COUNT),
        super::HARVEST_MONSTER_SKIN_COUNT
    );
    assert_eq!(
        session
            .app
            .world()
            .entity(candidate)
            .get::<super::HarvestMonsterState>()
            .expect("candidate state")
            .remaining_skin_count,
        super::HARVEST_MONSTER_SKIN_COUNT - 1
    );
}

