#[test]
fn trainer_is_static_passive_and_does_not_die_from_damage() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    assert_eq!(
        super::monster_disposition_for_ai(56),
        WorldEntityDisposition::Neutral
    );
    assert!(!super::monster_targets_players(56));

    let player_origin = Point { x: 900, y: 900 };
    let trainer_object_id = 98_897_u32;
    let trainer_origin = Point {
        x: player_origin.x + 1,
        y: player_origin.y,
    };
    set_player_position(&mut session, player_origin);
    let trainer = spawn_crystal_monster_for_test(
        &mut session,
        trainer_object_id,
        "Trainer",
        trainer_origin.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(trainer);
        entry.insert(MonsterVitals { hp: 3, max_hp: 3 });
        let mut agent = entry.get_mut::<MonsterAgent>().expect("trainer agent");
        agent.can_wander = true;
        agent.tracking_player = true;
        agent.hostile_to_player = true;
        agent.next_move_tick = current_tick;
        agent.next_attack_tick = current_tick;
        agent.next_route_tick = current_tick;
        agent.route = vec![super::RouteStep {
            location: Point {
                x: trainer_origin.x + 1,
                y: trainer_origin.y,
            },
            delay_ticks: 0,
        }];
    }
    sync_visible_objects(&mut session);

    for _ in 0..3 {
        let packets = session.tick();
        assert_eq!(
            entity_position(session.app.world(), trainer).expect("trainer position"),
            trainer_origin
        );
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectWalk { movement }
                    if movement.object_id == trainer_object_id
            )
        }));
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info } if info.object_id == trainer_object_id
            )
        }));
    }

    let mut packets = Vec::new();
    let tick = runtime_tick(session.app.world());
    assert!(!super::damage_monster_entity(
        session.app.world_mut(),
        trainer,
        120,
        tick,
        &mut packets,
    ));
    let expected_damage_message = super::format_localized_text(
        super::current_language(session.app.world()),
        "server.PetInflictedDamageDps",
        [
            "120".to_string(),
            "Physical Agility".to_string(),
            "120.00".to_string(),
            super::localized_text_or_fallback(
                super::current_language(session.app.world()),
                "server.You",
                "You",
            ),
        ],
    );
    assert!(packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::Chat { message, chat_type }
                if *chat_type == ChatType::Trainer
                    && message == &expected_damage_message
        )
    }));
    assert_eq!(
        session
            .app
            .world()
            .entity(trainer)
            .get::<MonsterVitals>()
            .expect("trainer vitals")
            .hp,
        3
    );
    assert!(!packet_has_object_died(&packets, trainer_object_id));

    let mut idle_packets = Vec::new();
    for _ in 0..=super::TRAINER_DAMAGE_REPORT_IDLE_TICKS {
        idle_packets = session.tick();
    }
    let expected_average_message = super::format_localized_text(
        super::current_language(session.app.world()),
        "server.AverageDamageOnTrainer",
        ["120".to_string(), "120.00".to_string()],
    );
    assert!(idle_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::Chat { message, chat_type }
                if *chat_type == ChatType::Trainer
                    && message == &expected_average_message
        )
    }));
}

#[test]
fn toxic_ghoul_applies_green_poison_status_from_crystal_melee() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let toxic_object_id = 98_888_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let toxic = spawn_crystal_monster_for_test(
        &mut session,
        toxic_object_id,
        "ToxicGhoul",
        Point {
            x: player_origin.x + 1,
            y: player_origin.y,
        },
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(toxic);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("toxic ghoul agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let mut saw_attack = false;
    for _ in 0..80 {
        let packets = session.tick();
        saw_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info }
                    if info.object_id == toxic_object_id && info.attack_type == 0
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info } if info.object_id == toxic_object_id
            )
        }));
        if session
            .world_snapshot()
            .active_buffs
            .iter()
            .any(|buff| buff.key == super::TOXIC_GHOUL_GREEN_POISON_BUFF_KEY)
        {
            break;
        }
    }

    assert!(saw_attack);
    assert!(session.world_snapshot().player_hp.expect("player hp") < before_hp);
    assert!(session
        .world_snapshot()
        .active_buffs
        .iter()
        .any(|buff| buff.key == super::TOXIC_GHOUL_GREEN_POISON_BUFF_KEY));
}

#[test]
fn thunder_element_delays_area_attack_packet_and_ignores_normal_damage() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let thunder_object_id = 98_889_u32;
    set_player_position(&mut session, player_origin.clone());
    let thunder = spawn_crystal_monster_for_test(
        &mut session,
        thunder_object_id,
        "ElectricElement",
        Point {
            x: player_origin.x + 1,
            y: player_origin.y,
        },
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(thunder);
        let mut agent = entry
            .get_mut::<MonsterAgent>()
            .expect("thunder element agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let before_thunder_hp = session
        .app
        .world()
        .entity(thunder)
        .get::<MonsterVitals>()
        .expect("thunder vitals")
        .hp;
    let _ = session.attack(thunder_object_id);
    for _ in 0..2 {
        let _ = session.tick();
    }
    let after_thunder_hp = session
        .app
        .world()
        .entity(thunder)
        .get::<MonsterVitals>()
        .expect("thunder vitals")
        .hp;
    assert_eq!(after_thunder_hp, before_thunder_hp);

    let before_player_hp = session.world_snapshot().player_hp.expect("player hp");
    let mut saw_due_attack = false;
    let mut saw_struck = false;
    for _ in 0..20 {
        let packets = session.tick();
        saw_due_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info }
                    if info.object_id == thunder_object_id && info.attack_type == 0
            )
        });
        saw_struck |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == thunder_object_id
            )
        });
        if saw_due_attack && saw_struck {
            break;
        }
    }

    assert!(saw_due_attack);
    assert!(saw_struck);
    assert!(session.world_snapshot().player_hp.expect("player hp") < before_player_hp);
}

#[test]
fn thunder_element_can_reposition_before_area_attack() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 340, y: 270 };
    let thunder_object_id = 98_887_u32;
    let ally_object_id = 98_886_u32;
    set_player_position(&mut session, player_origin.clone());
    let player = player_entity(session.app.world()).expect("player entity");
    session
        .app
        .world_mut()
        .entity_mut(player)
        .insert(PlayerVitals {
            hp: 1_000,
            max_hp: 1_000,
            mp: 200,
        });
    let thunder = spawn_crystal_monster_for_test(
        &mut session,
        thunder_object_id,
        "ElectricElement",
        Point {
            x: player_origin.x + 2,
            y: player_origin.y,
        },
        MirDirection::Left,
        true,
    );
    let ally = spawn_crystal_monster_for_test(
        &mut session,
        ally_object_id,
        "Hen",
        Point {
            x: player_origin.x,
            y: player_origin.y + 2,
        },
        MirDirection::Up,
        false,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut thunder_entry = session.app.world_mut().entity_mut(thunder);
        let mut agent = thunder_entry
            .get_mut::<MonsterAgent>()
            .expect("thunder element agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 1;
        agent.move_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    {
        let mut ally_entry = session.app.world_mut().entity_mut(ally);
        ally_entry.insert(MonsterVitals { hp: 80, max_hp: 80 });
        let mut agent = ally_entry.get_mut::<MonsterAgent>().expect("ally agent");
        agent.can_wander = false;
        agent.tracking_player = false;
    }
    sync_visible_objects(&mut session);

    let before_ally_hp = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    let mut saw_walk = false;
    let mut saw_ally_struck = false;
    for _ in 0..30 {
        let packets = session.tick();
        saw_walk |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectWalk { movement }
                    if movement.object_id == thunder_object_id
                        && tile_distance(&movement.position, &player_origin) <= 2
            )
        });
        saw_ally_struck |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectStruck { info }
                    if info.object_id == ally_object_id
                        && info.attacker_id == thunder_object_id
            )
        });
        if saw_walk && saw_ally_struck {
            break;
        }
    }

    assert!(saw_walk);
    assert!(saw_ally_struck);
    assert!(
        session
            .app
            .world()
            .entity(ally)
            .get::<MonsterVitals>()
            .expect("ally vitals")
            .hp
            < before_ally_hp
    );
}

