#[test]
fn oma_king_close_line_branch_pushes_and_can_paralyze_before_line_damage() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let player_object_id = entity_object_id(session.app.world(), player).expect("player object id");
    let player_origin = (320..380)
        .flat_map(|x| (250..310).map(move |y| Point { x, y }))
        .find(|point| {
            let king_position = Point {
                x: point.x + 1,
                y: point.y,
            };
            can_occupy(session.app.world(), point.clone(), Some(player))
                && can_occupy(session.app.world(), king_position, None)
                && (1..=5).all(|amount| {
                    can_occupy(
                        session.app.world(),
                        Point {
                            x: point.x - amount,
                            y: point.y,
                        },
                        Some(player),
                    )
                })
        })
        .expect("test should find an open OmaKing push lane");
    let king_position = Point {
        x: player_origin.x + 1,
        y: player_origin.y,
    };
    let king_object_id = 99_970_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let king = spawn_crystal_monster_for_test(
        &mut session,
        king_object_id,
        "OmaKing",
        king_position,
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    let mut branch_tick = current_tick + 1;
    while branch_tick % 8 != 0 || branch_tick % 3 == 0 {
        branch_tick += 1;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(king);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("oma king agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = branch_tick;
        agent.next_move_tick = branch_tick;
    }
    sync_visible_objects(&mut session);

    let mut branch_packets = Vec::new();
    while runtime_tick(session.app.world()) < branch_tick {
        branch_packets = session.tick();
    }
    assert!(branch_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectAttack { info }
            if info.object_id == king_object_id
                && info.attack_type == 0
                && info.direction == MirDirection::Left
    )));
    assert_eq!(
        branch_packets.iter().find_map(|packet| match packet {
            ServerPacket::ObjectWalk { movement } if movement.object_id == player_object_id => {
                Some(movement.position.clone())
            }
            _ => None,
        }),
        Some(Point {
            x: player_origin.x - 5,
            y: player_origin.y,
        })
    );
    assert!(session
        .world_snapshot()
        .active_buffs
        .iter()
        .any(|buff| buff.key == super::CAVE_MAGGOT_PARALYSIS_BUFF_KEY));

    let followup_packets = session.tick();
    assert!(!followup_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Struck { info } if info.attacker_id == king_object_id
    )));
    assert_eq!(
        session.world_snapshot().player_hp.expect("player hp"),
        before_hp
    );
}

#[test]
fn oma_king_close_line_branch_hits_forward_targets() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let king_position = Point {
        x: player_origin.x + 2,
        y: player_origin.y,
    };
    let ally_position = Point {
        x: player_origin.x + 1,
        y: player_origin.y,
    };
    let king_object_id = 99_971_u32;
    let ally_object_id = 99_972_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin);
    let king = spawn_crystal_monster_for_test(
        &mut session,
        king_object_id,
        "OmaKing",
        king_position,
        MirDirection::Left,
        true,
    );
    let ally = spawn_crystal_monster_for_test(
        &mut session,
        ally_object_id,
        "BugBat",
        ally_position,
        MirDirection::Left,
        false,
    );
    let current_tick = runtime_tick(session.app.world());
    let mut branch_tick = current_tick + 1;
    while branch_tick % 3 == 0 {
        branch_tick += 1;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(king);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("oma king agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = branch_tick;
        agent.next_move_tick = branch_tick;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(ally);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
        agent.can_wander = false;
        agent.tracking_player = false;
    }
    let ally_hp_before = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    sync_visible_objects(&mut session);

    let mut branch_packets = Vec::new();
    while runtime_tick(session.app.world()) < branch_tick {
        branch_packets = session.tick();
    }
    assert!(branch_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectAttack { info }
            if info.object_id == king_object_id && info.attack_type == 0
    )));

    let hit_packets = session.tick();
    assert!(hit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Struck { info } if info.attacker_id == king_object_id
    )));
    assert!(hit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectStruck { info }
            if info.object_id == ally_object_id && info.attacker_id == king_object_id
    )));
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "OmaKing close line branch should use imported Crystal DC damage"
    );
    let ally_hp_after = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    assert!(ally_hp_after < ally_hp_before);
}

#[test]
fn great_fox_spirit_is_static_and_uses_seven_tile_range_attack() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let player_object_id = entity_object_id(session.app.world(), player).expect("player object id");
    let player_origin = Point { x: 900, y: 900 };
    let fox_position = Point {
        x: player_origin.x + 7,
        y: player_origin.y,
    };
    let fox_object_id = 98_942_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let fox = spawn_crystal_monster_for_test(
        &mut session,
        fox_object_id,
        "GreatFoxSpirit",
        fox_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(fox);
        let agent = entry.get::<MonsterAgent>().expect("great fox spirit agent");
        assert!(super::monster_in_attack_range(
            agent,
            &fox_position,
            &player_origin
        ));
        assert!(!super::monster_in_attack_range(
            agent,
            &fox_position,
            &Point {
                x: fox_position.x - 8,
                y: fox_position.y,
            }
        ));
        assert!(!super::monster_can_chase_player(agent));
        assert!(!super::monster_can_follow_route(agent));
        let mut agent = entry
            .get_mut::<MonsterAgent>()
            .expect("great fox spirit agent");
        agent.can_wander = true;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let mut saw_range_attack = false;
    let mut saw_struck = false;
    for _ in 0..8 {
        let packets = session.tick();
        saw_range_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info }
                    if info.object_id == fox_object_id
                        && info.target_id == player_object_id
                        && info.direction == MirDirection::Left
            )
        });
        saw_struck |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == fox_object_id
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info } if info.object_id == fox_object_id
            )
        }));
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectWalk { movement } if movement.object_id == fox_object_id
            )
        }));
        if saw_range_attack && saw_struck {
            break;
        }
    }

    assert_eq!(
        entity_position(session.app.world(), fox).expect("great fox spirit position"),
        fox_position
    );
    assert!(saw_range_attack);
    assert!(saw_struck);
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "GreatFoxSpirit ranged branch should use imported Crystal DC damage"
    );
}

#[test]
fn great_fox_spirit_fans_out_and_applies_slow_paralysis() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_object_id = current_player_object_id(session.app.world()).expect("player object id");
    let player_origin = Point { x: 900, y: 900 };
    let fox_position = Point {
        x: player_origin.x + 7,
        y: player_origin.y,
    };
    let ally_position = Point {
        x: fox_position.x - 1,
        y: fox_position.y + 1,
    };
    let current_tick = runtime_tick(session.app.world());
    let attack_tick = current_tick + 1;
    let damage_tick = attack_tick + super::combat_delay_ticks(300);
    let fox_object_id = (99_960_u32..100_500_u32)
        .find(|object_id| {
            super::deterministic_chance_roll(damage_tick, *object_id, 500, 5)
                && super::deterministic_chance_roll(damage_tick, *object_id, 501, 5)
        })
        .expect("test object id should satisfy deterministic GreatFoxSpirit poison rolls");
    let ally_object_id = 99_959_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin);
    let fox = spawn_crystal_monster_for_test(
        &mut session,
        fox_object_id,
        "GreatFoxSpirit",
        fox_position,
        MirDirection::Left,
        true,
    );
    let ally = spawn_crystal_monster_for_test(
        &mut session,
        ally_object_id,
        "BugBat",
        ally_position,
        MirDirection::Left,
        false,
    );
    {
        let mut entry = session.app.world_mut().entity_mut(fox);
        let mut agent = entry
            .get_mut::<MonsterAgent>()
            .expect("great fox spirit agent");
        agent.can_wander = true;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(ally);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
        agent.can_wander = false;
        agent.tracking_player = false;
    }
    let ally_hp_before = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    sync_visible_objects(&mut session);

    let attack_packets = session.tick();
    assert!(attack_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectRangeAttack { info } if info.object_id == fox_object_id
    )));
    assert!(attack_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectEffect { info }
            if info.object_id == player_object_id
                && info.effect == super::SPELL_EFFECT_GREAT_FOX_SPIRIT
    )));
    assert!(attack_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectEffect { info }
            if info.object_id == ally_object_id
                && info.effect == super::SPELL_EFFECT_GREAT_FOX_SPIRIT
    )));

    let hit_packets = session.tick();
    assert!(hit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Struck { info } if info.attacker_id == fox_object_id
    )));
    assert!(hit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectStruck { info }
            if info.object_id == ally_object_id && info.attacker_id == fox_object_id
    )));
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "GreatFoxSpirit fanout should preserve imported Crystal DC damage"
    );
    assert!(session
        .world_snapshot()
        .active_buffs
        .iter()
        .any(|buff| buff.key == super::ICE_GUARD_SLOW_BUFF_KEY));
    assert!(session
        .world_snapshot()
        .active_buffs
        .iter()
        .any(|buff| buff.key == super::CAVE_MAGGOT_PARALYSIS_BUFF_KEY));
    let ally_hp_after = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    assert!(ally_hp_after < ally_hp_before);
}

