#[test]
fn mir_statue_lethal_damage_sleeps_then_wakes_full_health() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let statue_position = Point {
        x: player_origin.x + 5,
        y: player_origin.y,
    };
    let statue_object_id = 98_994_u32;
    set_player_position(&mut session, player_origin);
    let statue = spawn_crystal_monster_for_test(
        &mut session,
        statue_object_id,
        "MirStatue",
        statue_position,
        MirDirection::Left,
        true,
    );
    sync_visible_objects(&mut session);

    let max_hp = session
        .app
        .world()
        .entity(statue)
        .get::<MonsterVitals>()
        .expect("mir statue vitals")
        .max_hp;
    let current_tick = runtime_tick(session.app.world());
    let mut sleep_packets = Vec::new();
    assert!(!super::damage_monster_entity(
        session.app.world_mut(),
        statue,
        i32::MAX,
        current_tick,
        &mut sleep_packets,
    ));
    assert!(!packet_has_object_died(&sleep_packets, statue_object_id));
    assert!(sleep_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectHealth { info }
            if info.object_id == statue_object_id && info.percent == 0
    )));

    let vitals = session
        .app
        .world()
        .entity(statue)
        .get::<MonsterVitals>()
        .expect("sleeping mir statue vitals");
    assert_eq!(vitals.hp, 0);
    assert_eq!(vitals.max_hp, max_hp);
    let ai_state = session
        .app
        .world()
        .entity(statue)
        .get::<MonsterAiState>()
        .copied()
        .expect("sleeping mir statue ai state");
    assert!(ai_state.mode);
    assert_eq!(
        ai_state.next_state_tick,
        current_tick + super::DRAGON_STATUE_SLEEP_DURATION_TICKS
    );
    let agent = session
        .app
        .world()
        .entity(statue)
        .get::<MonsterAgent>()
        .expect("sleeping mir statue agent");
    assert!(!agent.dead);
    assert!(!agent.tracking_player);

    let mut immune_packets = Vec::new();
    assert!(!super::damage_monster_entity(
        session.app.world_mut(),
        statue,
        i32::MAX,
        current_tick + 1,
        &mut immune_packets,
    ));
    assert!(!packet_has_object_health(&immune_packets, statue_object_id));
    assert!(!packet_has_object_died(&immune_packets, statue_object_id));

    let wake_tick = runtime_tick(session.app.world());
    session
        .app
        .world_mut()
        .entity_mut(statue)
        .get_mut::<MonsterAiState>()
        .expect("sleeping mir statue ai state")
        .next_state_tick = wake_tick;
    let wake_packets = session.tick();
    assert!(wake_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectHealth { info }
            if info.object_id == statue_object_id && info.percent == 100
    )));
    let vitals = session
        .app
        .world()
        .entity(statue)
        .get::<MonsterVitals>()
        .expect("woken mir statue vitals");
    assert_eq!(vitals.hp, max_hp);
    let ai_state = session
        .app
        .world()
        .entity(statue)
        .get::<MonsterAiState>()
        .copied()
        .expect("woken mir statue ai state");
    assert!(!ai_state.mode);
}

#[test]
fn guardian_rock_is_static_immune_and_emits_range_pull_packet() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let rock_position = Point {
        x: player_origin.x + 5,
        y: player_origin.y,
    };
    let rock_object_id = 98_931_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let rock = spawn_crystal_monster_for_test(
        &mut session,
        rock_object_id,
        "GuardianRock",
        rock_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(rock);
        let agent = entry.get::<MonsterAgent>().expect("guardian rock agent");
        assert!(super::monster_in_attack_range(
            agent,
            &rock_position,
            &player_origin
        ));
        assert!(!super::monster_can_chase_player(agent));
        assert!(!super::monster_can_follow_route(agent));
        assert!(super::ignores_monster_damage(agent));
        let mut agent = entry
            .get_mut::<MonsterAgent>()
            .expect("guardian rock agent");
        agent.can_wander = true;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let mut saw_range_attack = false;
    for _ in 0..4 {
        let packets = session.tick();
        saw_range_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info }
                    if info.object_id == rock_object_id
                        && info.direction == MirDirection::Left
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == rock_object_id
            )
        }));
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectWalk { movement } if movement.object_id == rock_object_id
            )
        }));
        if saw_range_attack {
            break;
        }
    }

    assert_eq!(
        entity_position(session.app.world(), rock).expect("guardian rock position"),
        rock_position
    );
    assert!(saw_range_attack);
    assert_eq!(
        session.world_snapshot().player_hp.expect("player hp"),
        before_hp
    );

    let before_rock_hp = session
        .app
        .world()
        .entity(rock)
        .get::<MonsterVitals>()
        .expect("guardian rock vitals")
        .hp;
    let _ = session.attack(rock_object_id);
    for _ in 0..2 {
        let _ = session.tick();
    }
    let after_rock_hp = session
        .app
        .world()
        .entity(rock)
        .get::<MonsterVitals>()
        .expect("guardian rock vitals")
        .hp;
    assert_eq!(after_rock_hp, before_rock_hp);
}

#[test]
fn guardian_rock_delays_packet_and_pulls_player_toward_rock() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let player_origin = (320..380)
        .flat_map(|x| (250..310).map(move |y| Point { x, y }))
        .find(|point| {
            (0..=5).all(|offset| {
                can_occupy(
                    session.app.world(),
                    Point {
                        x: point.x + offset,
                        y: point.y,
                    },
                    if offset == 0 { Some(player) } else { None },
                )
            })
        })
        .expect("test should find an open GuardianRock pull lane");
    let rock_position = Point {
        x: player_origin.x + 5,
        y: player_origin.y,
    };
    let rock_object_id = 98_991_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let rock = spawn_crystal_monster_for_test(
        &mut session,
        rock_object_id,
        "GuardianRock",
        rock_position,
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(rock);
        let mut agent = entry
            .get_mut::<MonsterAgent>()
            .expect("guardian rock agent");
        agent.can_wander = true;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let windup_packets = session.tick();
    assert!(!windup_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectRangeAttack { info } if info.object_id == rock_object_id
        )
    }));

    let pull_packets = session.tick();
    assert!(pull_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectRangeAttack { info }
                if info.object_id == rock_object_id && info.direction == MirDirection::Left
        )
    }));
    assert_eq!(
        pull_packets.iter().find_map(|packet| match packet {
            ServerPacket::ObjectWalk { movement } => Some(movement.position.clone()),
            _ => None,
        }),
        Some(Point {
            x: player_origin.x + 4,
            y: player_origin.y,
        })
    );
    assert_eq!(
        session.world_snapshot().player_hp.expect("player hp"),
        before_hp
    );
}

#[test]
fn red_moon_evil_is_static_and_hits_from_view_range() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let evil_position = Point {
        x: player_origin.x + 8,
        y: player_origin.y,
    };
    let evil_object_id = 98_933_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let evil = spawn_crystal_monster_for_test(
        &mut session,
        evil_object_id,
        "RedMoonEvil",
        evil_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(evil);
        let agent = entry.get::<MonsterAgent>().expect("red moon evil agent");
        assert!(super::monster_in_attack_range(
            agent,
            &evil_position,
            &player_origin
        ));
        assert!(!super::monster_can_chase_player(agent));
        assert!(!super::monster_can_follow_route(agent));
        let mut agent = entry
            .get_mut::<MonsterAgent>()
            .expect("red moon evil agent");
        agent.can_wander = true;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let mut saw_attack = false;
    let mut saw_struck = false;
    for _ in 0..8 {
        let packets = session.tick();
        saw_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info }
                    if info.object_id == evil_object_id && info.attack_type == 0
            )
        });
        saw_struck |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == evil_object_id
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info } if info.object_id == evil_object_id
            )
        }));
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectWalk { movement } if movement.object_id == evil_object_id
            )
        }));
        if saw_attack && saw_struck {
            break;
        }
    }

    assert_eq!(
        entity_position(session.app.world(), evil).expect("red moon evil position"),
        evil_position
    );
    assert!(saw_attack);
    assert!(saw_struck);
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "RedMoonEvil view-range attack should use imported Crystal DC damage"
    );
}

#[test]
fn red_moon_evil_view_attack_fans_out_to_all_targets_in_range() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_object_id = current_player_object_id(session.app.world()).expect("player object id");
    let player_origin = Point { x: 900, y: 900 };
    let evil_position = Point {
        x: player_origin.x + 8,
        y: player_origin.y,
    };
    let ally_position = Point {
        x: player_origin.x + 2,
        y: player_origin.y + 1,
    };
    let evil_object_id = 99_980_u32;
    let ally_object_id = 99_981_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin);
    let evil = spawn_crystal_monster_for_test(
        &mut session,
        evil_object_id,
        "RedMoonEvil",
        evil_position,
        MirDirection::Left,
        true,
    );
    let ally = spawn_crystal_monster_for_test(
        &mut session,
        ally_object_id,
        "BugBat",
        ally_position,
        MirDirection::Left,
        false,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(evil);
        let mut agent = entry
            .get_mut::<MonsterAgent>()
            .expect("red moon evil agent");
        agent.can_wander = true;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(ally);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
        agent.can_wander = false;
        agent.tracking_player = false;
    }
    let ally_hp_before = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    sync_visible_objects(&mut session);

    let attack_packets = session.tick();
    assert!(attack_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectAttack { info }
            if info.object_id == evil_object_id && info.attack_type == 0
    )));
    assert!(attack_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectEffect { info }
            if info.object_id == player_object_id
                && info.effect == super::SPELL_EFFECT_RED_MOON_EVIL
    )));
    assert!(attack_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectEffect { info }
            if info.object_id == ally_object_id
                && info.effect == super::SPELL_EFFECT_RED_MOON_EVIL
    )));

    let hit_packets = session.tick();
    assert!(hit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Struck { info } if info.attacker_id == evil_object_id
    )));
    assert!(hit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectStruck { info }
            if info.object_id == ally_object_id && info.attacker_id == evil_object_id
    )));
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "RedMoonEvil fanout should preserve imported Crystal DC damage"
    );
    let ally_hp_after = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    assert!(ally_hp_after < ally_hp_before);
}

#[test]
fn evil_centipede_reveals_near_player_and_attacks_from_view_range() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let centipede_position = Point {
        x: player_origin.x + 2,
        y: player_origin.y,
    };
    let centipede_object_id = 98_937_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let centipede = spawn_crystal_monster_for_test(
        &mut session,
        centipede_object_id,
        "EvilCentipede",
        centipede_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(centipede);
        let agent = entry.get::<MonsterAgent>().expect("evil centipede agent");
        let ai_state = entry
            .get::<MonsterAiState>()
            .copied()
            .expect("evil centipede ai state");
        assert!(ai_state.hidden);
        assert!(super::monster_in_attack_range(
            agent,
            &centipede_position,
            &player_origin
        ));
        assert!(!super::monster_can_chase_player(agent));
        assert!(!super::monster_can_follow_route(agent));
        let mut agent = entry
            .get_mut::<MonsterAgent>()
            .expect("evil centipede agent");
        agent.can_wander = true;
        agent.tracking_player = false;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    assert!(!session.visible_objects.contains(&centipede_object_id));

    let mut saw_show = false;
    let mut saw_attack = false;
    let mut saw_struck = false;
    for _ in 0..10 {
        let packets = session.tick();
        saw_show |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectShow { object_id } if *object_id == centipede_object_id
            )
        });
        saw_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info }
                    if info.object_id == centipede_object_id && info.attack_type == 0
            )
        });
        saw_struck |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == centipede_object_id
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info }
                    if info.object_id == centipede_object_id
            )
        }));
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectWalk { movement }
                    if movement.object_id == centipede_object_id
            )
        }));
        if saw_show && saw_attack && saw_struck {
            break;
        }
    }

    assert_eq!(
        entity_position(session.app.world(), centipede).expect("evil centipede position"),
        centipede_position
    );
    let ai_state = session
        .app
        .world()
        .entity(centipede)
        .get::<MonsterAiState>()
        .copied()
        .expect("evil centipede ai state");
    assert!(!ai_state.hidden);
    assert!(saw_show);
    assert!(saw_attack);
    assert!(saw_struck);
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "EvilCentipede view-range attack should use imported Crystal DC damage"
    );
}

#[test]
fn evil_centipede_attack_fans_out_and_applies_crystal_poisons() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let centipede_position = Point {
        x: player_origin.x + 2,
        y: player_origin.y,
    };
    let ally_position = Point {
        x: player_origin.x + 1,
        y: player_origin.y + 1,
    };
    let current_tick = runtime_tick(session.app.world());
    let attack_tick = current_tick + 1;
    let damage_tick = attack_tick + super::combat_delay_ticks(500);
    let centipede_object_id = (99_982_u32..100_500_u32)
        .find(|object_id| {
            super::deterministic_chance_roll(damage_tick, *object_id, 140, 5)
                && super::deterministic_chance_roll(damage_tick, *object_id, 141, 15)
        })
        .expect("test object id should satisfy deterministic EvilCentipede poison rolls");
    let ally_object_id = 99_981_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin);
    let centipede = spawn_crystal_monster_for_test(
        &mut session,
        centipede_object_id,
        "EvilCentipede",
        centipede_position,
        MirDirection::Left,
        true,
    );
    let ally = spawn_crystal_monster_for_test(
        &mut session,
        ally_object_id,
        "BugBat",
        ally_position,
        MirDirection::Left,
        false,
    );
    {
        let mut entry = session.app.world_mut().entity_mut(centipede);
        {
            let mut ai_state = entry
                .get_mut::<MonsterAiState>()
                .expect("evil centipede ai state");
            ai_state.hidden = false;
        }
        let mut agent = entry
            .get_mut::<MonsterAgent>()
            .expect("evil centipede agent");
        agent.can_wander = true;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(ally);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
        agent.can_wander = false;
        agent.tracking_player = false;
    }
    let ally_hp_before = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    sync_visible_objects(&mut session);

    let attack_packets = session.tick();
    assert!(attack_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectAttack { info }
            if info.object_id == centipede_object_id && info.attack_type == 0
    )));

    let hit_packets = session.tick();
    assert!(hit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Struck { info } if info.attacker_id == centipede_object_id
    )));
    assert!(hit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectStruck { info }
            if info.object_id == ally_object_id && info.attacker_id == centipede_object_id
    )));
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "EvilCentipede fanout should preserve imported Crystal DC damage"
    );
    assert!(session
        .world_snapshot()
        .active_buffs
        .iter()
        .any(|buff| buff.key == super::TOXIC_GHOUL_GREEN_POISON_BUFF_KEY));
    assert!(session
        .world_snapshot()
        .active_buffs
        .iter()
        .any(|buff| buff.key == super::CAVE_MAGGOT_PARALYSIS_BUFF_KEY));
    let ally_hp_after = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    assert!(ally_hp_after < ally_hp_before);
}

#[test]
fn yimoogi_uses_crystal_seven_tile_range_attack_branch() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let yimoogi_position = Point {
        x: player_origin.x + 7,
        y: player_origin.y,
    };
    let yimoogi_object_id = 98_934_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let yimoogi = spawn_crystal_monster_for_test(
        &mut session,
        yimoogi_object_id,
        "Yimoogi",
        yimoogi_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(yimoogi);
        let agent = entry.get::<MonsterAgent>().expect("yimoogi agent");
        assert!(super::monster_in_attack_range(
            agent,
            &yimoogi_position,
            &player_origin
        ));
        assert!(!super::monster_in_attack_range(
            agent,
            &yimoogi_position,
            &Point {
                x: yimoogi_position.x - 8,
                y: yimoogi_position.y,
            }
        ));
        let mut agent = entry.get_mut::<MonsterAgent>().expect("yimoogi agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let mut saw_range_attack = false;
    let mut saw_struck = false;
    for _ in 0..8 {
        let packets = session.tick();
        saw_range_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info }
                    if info.object_id == yimoogi_object_id
                        && info.direction == MirDirection::Left
            )
        });
        saw_struck |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == yimoogi_object_id
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info } if info.object_id == yimoogi_object_id
            )
        }));
        if saw_range_attack && saw_struck {
            break;
        }
    }

    assert!(saw_range_attack);
    assert!(saw_struck);
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "Yimoogi ranged branch should use imported Crystal DC damage"
    );
}

#[test]
fn yimoogi_four_tile_poison_branch_uses_type_one_red_poison() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let yimoogi_position = Point {
        x: player_origin.x + 4,
        y: player_origin.y,
    };
    let yimoogi_object_id = 98_933_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin);
    let yimoogi = spawn_crystal_monster_for_test(
        &mut session,
        yimoogi_object_id,
        "Yimoogi",
        yimoogi_position,
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    let mut branch_tick = current_tick + 1;
    while branch_tick % 6 != 0 {
        branch_tick += 1;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(yimoogi);
        entry.insert(YimoogiState {
            spawn_tick: current_tick,
            child_spawned: true,
            is_child: false,
            final_teleport: false,
            sister_object_id: None,
        });
        let mut agent = entry.get_mut::<MonsterAgent>().expect("yimoogi agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = branch_tick;
        agent.next_move_tick = branch_tick;
    }
    sync_visible_objects(&mut session);

    let mut branch_packets = Vec::new();
    while runtime_tick(session.app.world()) < branch_tick {
        branch_packets = session.tick();
    }
    assert!(branch_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectAttack { info }
            if info.object_id == yimoogi_object_id && info.attack_type == 1
    )));
    assert!(!branch_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectRangeAttack { info } if info.object_id == yimoogi_object_id
    )));
    assert!(!branch_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Struck { info } if info.attacker_id == yimoogi_object_id
    )));
    assert!(session
        .world_snapshot()
        .active_buffs
        .iter()
        .any(|buff| buff.key == super::YIMOOGI_RED_POISON_BUFF_KEY));

    let followup_packets = session.tick();
    assert!(!followup_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Struck { info } if info.attacker_id == yimoogi_object_id
    )));
    assert_eq!(
        session.world_snapshot().player_hp.expect("player hp"),
        before_hp
    );
}

#[test]
fn yimoogi_spawns_sister_child_after_crystal_delay() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let yimoogi_position = Point {
        x: player_origin.x + 6,
        y: player_origin.y,
    };
    let yimoogi_object_id = 98_932_u32;
    set_player_position(&mut session, player_origin);
    let yimoogi = spawn_crystal_monster_for_test(
        &mut session,
        yimoogi_object_id,
        "Yimoogi",
        yimoogi_position,
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(yimoogi);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("yimoogi agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 100;
        agent.next_attack_tick = current_tick + 100;
        agent.next_move_tick = current_tick + 100;
    }
    sync_visible_objects(&mut session);

    let mut saw_spawn_attack = false;
    let mut child_object_id = None;
    for _ in 0..8 {
        let packets = session.tick();
        saw_spawn_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info }
                    if info.object_id == yimoogi_object_id && info.attack_type == 2
            )
        });
        if child_object_id.is_none() {
            child_object_id = packets.iter().find_map(|packet| match packet {
                ServerPacket::ObjectMonster { info }
                    if info.name == "Yimoogi" && info.object_id != yimoogi_object_id =>
                {
                    Some(info.object_id)
                }
                _ => None,
            });
        }
        if saw_spawn_attack && child_object_id.is_some() {
            break;
        }
    }

    let child_object_id = child_object_id.expect("Yimoogi child should spawn");
    assert!(saw_spawn_attack);
    let parent_state = session
        .app
        .world()
        .entity(yimoogi)
        .get::<YimoogiState>()
        .expect("parent Yimoogi state");
    assert!(parent_state.child_spawned);
    assert_eq!(parent_state.sister_object_id, Some(child_object_id));

    let child =
        entity_by_object_id(session.app.world(), child_object_id).expect("child Yimoogi entity");
    let child_entry = session.app.world().entity(child);
    let child_state = child_entry
        .get::<YimoogiState>()
        .expect("child Yimoogi state");
    assert!(child_state.is_child);
    assert_eq!(child_state.sister_object_id, Some(yimoogi_object_id));
    assert!(child_entry.get::<SummonedMonster>().is_none());
}

#[test]
fn yimoogi_final_teleport_spawns_white_serpents_at_old_location() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let yimoogi_position = Point {
        x: player_origin.x + 5,
        y: player_origin.y,
    };
    let yimoogi_object_id = 98_931_u32;
    set_player_position(&mut session, player_origin);
    let yimoogi = spawn_crystal_monster_for_test(
        &mut session,
        yimoogi_object_id,
        "Yimoogi",
        yimoogi_position.clone(),
        MirDirection::Left,
        true,
    );
    {
        let mut entry = session.app.world_mut().entity_mut(yimoogi);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("yimoogi agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 100;
        drop(agent);
        let max_hp = entry.get::<MonsterVitals>().expect("yimoogi vitals").max_hp;
        entry.insert(MonsterVitals {
            hp: max_hp / 10,
            max_hp,
        });
    }
    sync_visible_objects(&mut session);

    let packets = session.tick();
    let teleport = packets.iter().find_map(|packet| match packet {
        ServerPacket::ObjectWalk { movement }
            if movement.object_id == yimoogi_object_id && movement.position != yimoogi_position =>
        {
            Some(movement.position.clone())
        }
        _ => None,
    });
    let white_serpent_count = packets
        .iter()
        .filter(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectMonster { info }
                    if info.name == "WhiteSerpent" && info.location == yimoogi_position
            )
        })
        .count();

    assert!(teleport.is_some());
    assert_eq!(white_serpent_count, 2);
    let entry = session.app.world().entity(yimoogi);
    assert!(
        entry
            .get::<YimoogiState>()
            .expect("yimoogi state")
            .final_teleport
    );
    assert!(
        !entry
            .get::<MonsterAgent>()
            .expect("yimoogi agent")
            .tracking_player
    );
}

#[test]
fn yimoogi_suppresses_death_drops_while_sister_is_alive() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let yimoogi_object_id = 3001_u32;
    let child_object_id = 98_930_u32;
    let yimoogi_position = Point { x: 338, y: 273 };
    let child_position = Point { x: 338, y: 274 };
    let yimoogi = entity_by_object_id(session.app.world(), yimoogi_object_id)
        .expect("starter training dummy entity");
    let template = crystal_dynamic_monster_template("Yimoogi").expect("Yimoogi template");
    {
        let mut entry = session.app.world_mut().entity_mut(yimoogi);
        entry.insert((
            DisplayName::literal("Yimoogi"),
            Position(yimoogi_position.clone()),
            Facing(MirDirection::Left),
            MonsterVitals { hp: 1, max_hp: 1 },
            YimoogiState {
                spawn_tick: 0,
                child_spawned: true,
                is_child: false,
                final_teleport: true,
                sister_object_id: Some(child_object_id),
            },
        ));
        entry.remove::<HarvestMonsterState>();
        entry.remove::<super::PendingHarvestDrops>();
        let mut agent = entry.get_mut::<MonsterAgent>().expect("yimoogi agent");
        agent.image = template.monster_image;
        agent.ai = 36;
        agent.dead = false;
        agent.disposition = WorldEntityDisposition::Neutral;
        agent.hostile_to_player = false;
        agent.tracking_player = false;
        agent.can_wander = false;
        agent.next_attack_tick = 100;
        agent.next_move_tick = 100;
    }
    let child = spawn_crystal_monster_for_test(
        &mut session,
        child_object_id,
        "Yimoogi",
        child_position,
        MirDirection::Left,
        false,
    );
    {
        let mut entry = session.app.world_mut().entity_mut(child);
        entry.insert(YimoogiState {
            spawn_tick: 0,
            child_spawned: true,
            is_child: true,
            final_teleport: false,
            sister_object_id: Some(yimoogi_object_id),
        });
        let mut agent = entry.get_mut::<MonsterAgent>().expect("child agent");
        agent.can_wander = false;
        agent.tracking_player = false;
    }

    set_player_position(
        &mut session,
        Point {
            x: yimoogi_position.x - 1,
            y: yimoogi_position.y,
        },
    );
    sync_visible_objects(&mut session);
    let death_packets = attack_until_monster_dies(&mut session, yimoogi_object_id, 3);

    assert!(packet_has_object_died(&death_packets, yimoogi_object_id));
    assert!(!death_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectItem { .. } | ServerPacket::ObjectGold { .. }
        )
    }));
    assert!(!session
        .world_snapshot()
        .ground_drops
        .iter()
        .any(|drop| drop.name == "Training Splinter"));
}

#[test]
fn lamia_kirin_uses_crystal_two_tile_attack_shape() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let lamia_position = Point {
        x: player_origin.x + 2,
        y: player_origin.y,
    };
    let lamia_object_id = 98_935_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let lamia = spawn_crystal_monster_for_test(
        &mut session,
        lamia_object_id,
        "Lamia",
        lamia_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(lamia);
        let agent = entry.get::<MonsterAgent>().expect("lamia agent");
        assert!(super::monster_in_attack_range(
            agent,
            &lamia_position,
            &player_origin
        ));
        assert!(super::monster_in_attack_range(
            agent,
            &lamia_position,
            &Point {
                x: lamia_position.x - 2,
                y: lamia_position.y + 2,
            }
        ));
        assert!(!super::monster_in_attack_range(
            agent,
            &lamia_position,
            &Point {
                x: lamia_position.x - 1,
                y: lamia_position.y + 2,
            }
        ));
        let mut agent = entry.get_mut::<MonsterAgent>().expect("lamia agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let mut saw_attack = false;
    let mut saw_struck = false;
    for _ in 0..8 {
        let packets = session.tick();
        saw_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info }
                    if info.object_id == lamia_object_id && info.attack_type == 0
            )
        });
        saw_struck |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == lamia_object_id
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info } if info.object_id == lamia_object_id
            )
        }));
        if saw_attack && saw_struck {
            break;
        }
    }

    assert!(saw_attack);
    assert!(saw_struck);
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "Lamia/Kirin two-tile branch should use imported Crystal DC damage"
    );
}

