#[test]
fn tucson_general_opens_with_rage_packet_without_direct_damage() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let player_object_id = entity_object_id(session.app.world(), player).expect("player object id");
    let player_origin = Point { x: 900, y: 900 };
    let general_position = Point {
        x: player_origin.x + 8,
        y: player_origin.y,
    };
    let general_object_id = 98_948_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let general = spawn_crystal_monster_for_test(
        &mut session,
        general_object_id,
        "TucsonGeneral",
        general_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(general);
        let agent = entry.get::<MonsterAgent>().expect("tucson general agent");
        assert!(super::monster_in_attack_range(
            agent,
            &general_position,
            &player_origin
        ));
        assert!(!super::monster_in_attack_range(
            agent,
            &general_position,
            &Point {
                x: general_position.x - 10,
                y: general_position.y,
            }
        ));
        let mut agent = entry
            .get_mut::<MonsterAgent>()
            .expect("tucson general agent");
        agent.tracking_player = false;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let mut saw_rage = false;
    for _ in 0..4 {
        let packets = session.tick();
        saw_rage |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info }
                    if info.object_id == general_object_id
                        && info.target_id == player_object_id
                        && info.attack_type == 0
                        && info.direction == MirDirection::Left
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info } if info.object_id == general_object_id
            )
        }));
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == general_object_id
            )
        }));
        if saw_rage {
            break;
        }
    }

    assert!(saw_rage);
    assert_eq!(
        session.world_snapshot().player_hp.expect("player hp"),
        before_hp
    );
}

