#[test]
fn tucson_general_close_stomp_hits_area_and_applies_paralysis() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let player_origin = Point { x: 900, y: 900 };
    let general_position = Point {
        x: player_origin.x + 1,
        y: player_origin.y,
    };
    let ally_position = Point {
        x: general_position.x,
        y: general_position.y + 2,
    };
    let general_object_id = 98_971_u32;
    let ally_object_id = 98_972_u32;
    set_player_position(&mut session, player_origin);
    session
        .app
        .world_mut()
        .entity_mut(player)
        .insert(super::PlayerVitals {
            hp: 500,
            max_hp: 500,
            mp: 100,
        });
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    let expected_damage = {
        (super::crystal_monster_magic_damage("TucsonGeneral")
            - total_defence_bonus(session.app.world()))
        .max(1)
    };
    let general = spawn_crystal_monster_for_test(
        &mut session,
        general_object_id,
        "TucsonGeneral",
        general_position,
        MirDirection::Left,
        true,
    );
    let ally = spawn_crystal_monster_for_test(
        &mut session,
        ally_object_id,
        "BugBat",
        ally_position,
        MirDirection::Left,
        false,
    );
    let current_tick = runtime_tick(session.app.world());
    let mut branch_tick = current_tick + 1;
    while branch_tick % 4 != 0
        || !super::deterministic_chance_roll(
            branch_tick + super::combat_delay_ticks(500),
            general_object_id,
            7,
            super::TUCSON_GENERAL_PARALYSIS_CHANCE_DENOMINATOR,
        )
    {
        branch_tick += 1;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(general);
        {
            let mut agent = entry
                .get_mut::<MonsterAgent>()
                .expect("tucson general agent");
            agent.can_wander = false;
            agent.tracking_player = true;
            agent.attack_interval_ticks = 50;
            agent.next_attack_tick = branch_tick;
            agent.next_move_tick = branch_tick;
        }
        entry
            .get_mut::<MonsterAiState>()
            .expect("tucson general ai state")
            .next_state_tick = branch_tick + 100;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(ally);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
        agent.can_wander = false;
        agent.tracking_player = false;
    }
    let ally_hp_before = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    sync_visible_objects(&mut session);

    let mut branch_packets = Vec::new();
    while runtime_tick(session.app.world()) < branch_tick {
        branch_packets = session.tick();
    }
    assert!(branch_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectAttack { info }
            if info.object_id == general_object_id && info.attack_type == 1
    )));
    assert!(!branch_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectRangeAttack { info } if info.object_id == general_object_id
    )));

    let damage_packets = session.tick();
    assert!(damage_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Struck { info } if info.attacker_id == general_object_id
    )));
    assert!(damage_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectStruck { info }
            if info.object_id == ally_object_id && info.attacker_id == general_object_id
    )));
    assert_eq!(
        before_hp - session.world_snapshot().player_hp.expect("player hp"),
        expected_damage,
        "TucsonGeneral close stomp should use imported Crystal MC after defence"
    );
    assert!(session
        .world_snapshot()
        .active_buffs
        .iter()
        .any(|buff| buff.key == super::CAVE_MAGGOT_PARALYSIS_BUFF_KEY));
    let ally_hp_after = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    assert!(ally_hp_after < ally_hp_before);
}

