#[test]
fn armadillo_reveals_and_uses_primary_dc_melee() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let armadillo_position = Point {
        x: player_origin.x + 1,
        y: player_origin.y,
    };
    let armadillo_object_id = 98_952_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let armadillo = spawn_crystal_monster_for_test(
        &mut session,
        armadillo_object_id,
        "Armadillo",
        armadillo_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(armadillo);
        let ai_state = entry
            .get::<MonsterAiState>()
            .copied()
            .expect("armadillo ai state");
        assert!(ai_state.hidden);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("armadillo agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);
    assert!(!session.visible_objects.contains(&armadillo_object_id));

    let mut saw_show = false;
    let mut saw_dig_out_spell = false;
    let mut saw_attack = false;
    let mut saw_struck = false;
    for _ in 0..8 {
        let packets = session.tick();
        saw_show |= packets.iter().any(|packet| {
                matches!(packet, ServerPacket::ObjectShow { object_id } if *object_id == armadillo_object_id)
            });
        saw_dig_out_spell |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectSpell { info }
                    if info.spell == Spell::DigOutArmadillo
                        && info.location == armadillo_position
                        && info.direction == MirDirection::Left
                        && info.param
            )
        });
        saw_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info }
                    if info.object_id == armadillo_object_id
                        && info.attack_type == 0
                        && info.direction == MirDirection::Left
            )
        });
        saw_struck |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == armadillo_object_id
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info }
                    if info.object_id == armadillo_object_id
            )
        }));
        if saw_show && saw_dig_out_spell && saw_attack && saw_struck {
            break;
        }
    }

    assert!(saw_show);
    assert!(saw_dig_out_spell);
    assert!(saw_attack);
    assert!(saw_struck);
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 30,
        "Armadillo primary branch should use imported Crystal DC damage"
    );
}

