#[test]
fn restless_jar_is_static_and_emits_zero_mc_range_packet() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let player_object_id = entity_object_id(session.app.world(), player).expect("player object id");
    let player_origin = Point { x: 900, y: 900 };
    let jar_position = Point {
        x: player_origin.x + 6,
        y: player_origin.y,
    };
    let jar_object_id = 98_945_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let jar = spawn_crystal_monster_for_test(
        &mut session,
        jar_object_id,
        "RestlessJar",
        jar_position.clone(),
        MirDirection::Left,
        true,
    );
    {
        let world = session.app.world();
        let agent = world
            .entity(jar)
            .get::<MonsterAgent>()
            .expect("restless jar agent");
        assert_eq!(
            super::monster_attack_delay_ticks(agent, &jar_position, &player_origin),
            super::ranged_attack_delay_ticks(&jar_position, &player_origin)
        );
        assert_eq!(
            super::monster_attack_delay_ticks(agent, &jar_position, &player_origin),
            super::combat_delay_ticks(6 * 50 + 500)
        );
        assert_eq!(
            super::monster_attack_delay_ticks(
                agent,
                &Point {
                    x: player_origin.x + 1,
                    y: player_origin.y,
                },
                &player_origin,
            ),
            super::combat_delay_ticks(300)
        );
    }
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(jar);
        let agent = entry.get::<MonsterAgent>().expect("restless jar agent");
        assert!(super::monster_in_attack_range(
            agent,
            &jar_position,
            &player_origin
        ));
        assert!(!super::monster_can_chase_player(agent));
        assert!(!super::monster_can_follow_route(agent));
        let mut agent = entry.get_mut::<MonsterAgent>().expect("restless jar agent");
        agent.can_wander = true;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let mut saw_range_attack = false;
    for _ in 0..6 {
        let packets = session.tick();
        saw_range_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info }
                    if info.object_id == jar_object_id
                        && info.target_id == player_object_id
                        && info.direction == MirDirection::Left
                        && info.attack_type == 0
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info } if info.object_id == jar_object_id
            )
        }));
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectWalk { movement } if movement.object_id == jar_object_id
            )
        }));
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == jar_object_id
            )
        }));
        if saw_range_attack {
            break;
        }
    }

    assert_eq!(
        entity_position(session.app.world(), jar).expect("restless jar position"),
        jar_position
    );
    assert!(saw_range_attack);
    assert_eq!(
        session.world_snapshot().player_hp.expect("player hp"),
        before_hp
    );
}

#[test]
fn restless_jar_adjacent_spin_branch_fans_out() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let jar_position = Point {
        x: player_origin.x + 1,
        y: player_origin.y,
    };
    let ally_position = Point {
        x: jar_position.x,
        y: jar_position.y + 1,
    };
    let jar_object_id = 98_962_u32;
    let ally_object_id = 98_963_u32;
    set_player_position(&mut session, player_origin);
    let jar = spawn_crystal_monster_for_test(
        &mut session,
        jar_object_id,
        "RestlessJar",
        jar_position,
        MirDirection::Left,
        true,
    );
    let ally = spawn_crystal_monster_for_test(
        &mut session,
        ally_object_id,
        "BugBat",
        ally_position,
        MirDirection::Left,
        false,
    );
    let current_tick = runtime_tick(session.app.world());
    let mut branch_tick = current_tick + 1;
    while branch_tick % 3 == 2 {
        branch_tick += 1;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(jar);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("restless jar agent");
        agent.can_wander = true;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = branch_tick;
        agent.next_move_tick = branch_tick;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(ally);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
        agent.can_wander = false;
        agent.tracking_player = false;
    }
    let ally_hp_before = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    sync_visible_objects(&mut session);

    let mut branch_packets = Vec::new();
    while runtime_tick(session.app.world()) < branch_tick {
        branch_packets = session.tick();
    }
    assert!(branch_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectAttack { info }
            if info.object_id == jar_object_id && info.attack_type == 0
    )));

    let hit_packets = session.tick();
    assert!(hit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Struck { info } if info.attacker_id == jar_object_id
    )));
    assert!(hit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectStruck { info }
            if info.object_id == ally_object_id && info.attacker_id == jar_object_id
    )));
    let ally_hp_after = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    assert!(ally_hp_after < ally_hp_before);
}

