#[test]
fn black_tortoise_close_halfmoon_branch_hits_arc() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let drake_position = Point {
        x: player_origin.x + 1,
        y: player_origin.y,
    };
    let ally_position = Point {
        x: drake_position.x,
        y: drake_position.y - 1,
    };
    let drake_object_id = 98_976_u32;
    let ally_object_id = 98_977_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin);
    let drake = spawn_crystal_monster_for_test(
        &mut session,
        drake_object_id,
        "SmallDrake",
        drake_position,
        MirDirection::Left,
        true,
    );
    let ally = spawn_crystal_monster_for_test(
        &mut session,
        ally_object_id,
        "BugBat",
        ally_position,
        MirDirection::Left,
        false,
    );
    let current_tick = runtime_tick(session.app.world());
    let mut branch_tick = current_tick + 1;
    while branch_tick % 5 != 0 {
        branch_tick += 1;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(drake);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("small drake agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = branch_tick;
        agent.next_move_tick = branch_tick;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(ally);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
        agent.can_wander = false;
        agent.tracking_player = false;
    }
    let ally_hp_before = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    sync_visible_objects(&mut session);

    let mut branch_packets = Vec::new();
    while runtime_tick(session.app.world()) < branch_tick {
        branch_packets = session.tick();
    }
    assert!(branch_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectAttack { info }
            if info.object_id == drake_object_id && info.attack_type == 1
    )));
    assert!(!branch_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectRangeAttack { info } if info.object_id == drake_object_id
    )));

    let damage_packets = session.tick();
    assert!(damage_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Struck { info } if info.attacker_id == drake_object_id
    )));
    assert!(damage_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectStruck { info }
            if info.object_id == ally_object_id && info.attacker_id == drake_object_id
    )));
    assert!(session.world_snapshot().player_hp.expect("player hp") < before_hp);
    let ally_hp_after = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    assert!(ally_hp_after < ally_hp_before);
}

