#[test]
fn respawn_restores_special_monster_initial_ai_state() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let current_tick = runtime_tick(session.app.world());
    let zuma_object_id = 98_889_u32;
    let plant_object_id = 98_890_u32;

    let zuma_entity = session
        .app
        .world_mut()
        .spawn((
            WorldObject,
            Monster,
            ObjectId(zuma_object_id),
            DisplayName::literal("Respawn Zuma"),
            Position(Point { x: 910, y: 910 }),
            Facing(MirDirection::Left),
            SpawnSlotRef {
                rule_index: 0,
                slot_index: 0,
            },
            MonsterVitals { hp: 0, max_hp: 50 },
            MonsterAgent {
                image: 65,
                dead: true,
                patrol_origin: Point { x: 910, y: 910 },
                ai: 15,
                disposition: WorldEntityDisposition::Hostile,
                hostile_to_player: true,
                tracking_player: true,
                view_range: 8,
                can_wander: true,
                move_interval_ticks: 1,
                attack_interval_ticks: 1,
                next_move_tick: current_tick,
                next_attack_tick: current_tick,
                route: Vec::new(),
                route_index: 0,
                route_waiting: false,
                next_route_tick: current_tick,
            },
            MonsterAiState {
                hidden: false,
                extra: false,
                extra_byte: 0,
                mode: false,
                next_state_tick: 99,
            },
        ))
        .id();

    let plant_entity = session
        .app
        .world_mut()
        .spawn((
            WorldObject,
            Monster,
            ObjectId(plant_object_id),
            DisplayName::literal("Respawn Plant"),
            Position(Point { x: 911, y: 910 }),
            Facing(MirDirection::Left),
            SpawnSlotRef {
                rule_index: 1,
                slot_index: 0,
            },
            MonsterVitals { hp: 0, max_hp: 50 },
            MonsterAgent {
                image: 43,
                dead: true,
                patrol_origin: Point { x: 911, y: 910 },
                ai: 5,
                disposition: WorldEntityDisposition::Hostile,
                hostile_to_player: true,
                tracking_player: true,
                view_range: 7,
                can_wander: true,
                move_interval_ticks: 1,
                attack_interval_ticks: 1,
                next_move_tick: current_tick,
                next_attack_tick: current_tick,
                route: Vec::new(),
                route_index: 0,
                route_waiting: false,
                next_route_tick: current_tick,
            },
            MonsterAiState {
                hidden: false,
                extra: false,
                extra_byte: 0,
                mode: false,
                next_state_tick: 77,
            },
        ))
        .id();

    session.app.world_mut().insert_resource(MonsterSpawnTable {
        rules: vec![
            MonsterSpawnRule {
                name: "Respawn Zuma".to_string(),
                image: 65,
                direction: MirDirection::Left,
                respawn_schedule: MonsterRespawnSchedule::FixedTicks {
                    delay_ticks: 1,
                    random_delay_ticks: 0,
                },
                ai: 15,
                disposition: WorldEntityDisposition::Hostile,
                hostile_to_player: true,
                view_range: 8,
                can_wander: true,
                move_interval_ticks: 1,
                attack_interval_ticks: 1,
                max_hp: 50,
                route: Vec::new(),
                slots: vec![MonsterSpawnSlot {
                    entity: Some(zuma_entity),
                    object_id: zuma_object_id,
                    spawn_position: Point { x: 910, y: 910 },
                    next_respawn_tick: Some(current_tick + 1),
                }],
            },
            MonsterSpawnRule {
                name: "Respawn Plant".to_string(),
                image: 43,
                direction: MirDirection::Left,
                respawn_schedule: MonsterRespawnSchedule::FixedTicks {
                    delay_ticks: 1,
                    random_delay_ticks: 0,
                },
                ai: 5,
                disposition: WorldEntityDisposition::Hostile,
                hostile_to_player: true,
                view_range: 7,
                can_wander: true,
                move_interval_ticks: 1,
                attack_interval_ticks: 1,
                max_hp: 50,
                route: Vec::new(),
                slots: vec![MonsterSpawnSlot {
                    entity: Some(plant_entity),
                    object_id: plant_object_id,
                    spawn_position: Point { x: 911, y: 910 },
                    next_respawn_tick: Some(current_tick + 1),
                }],
            },
        ],
    });

    let _ = session.tick();

    let zuma_state = session
        .app
        .world()
        .entity(zuma_entity)
        .get::<MonsterAiState>()
        .copied()
        .expect("zuma ai state");
    let plant_state = session
        .app
        .world()
        .entity(plant_entity)
        .get::<MonsterAiState>()
        .copied()
        .expect("plant ai state");
    assert!(zuma_state.extra);
    assert!(!zuma_state.hidden);
    assert!(plant_state.hidden);
    assert!(!plant_state.extra);
}

