#[test]
fn crystal_npc_buy_item_dead_player_is_silent_and_preserves_state() {
    let mut session = SimulationSession::new(wicked_trader_config());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let _ = session.interact(4990);
    let buy_sell_packets = session.select_npc_dialog_target("@BuySell");
    let ServerPacket::NPCGoods { list, .. } = &buy_sell_packets[0] else {
        panic!("first buy/sell packet should be NPCGoods");
    };
    let hp_drug = list
        .iter()
        .find(|item| item.item_index == 658 && item.count == 1)
        .expect("Wicked Trader should sell one-count HP drug");
    let item_index = hp_drug.unique_id;
    let state_before = {
        let inventory = session.app.world().resource::<InventoryResource>();
        let player = session.app.world().resource::<PlayerRuntimeResource>();
        (
            player.gold,
            inventory
                .inventory_items
                .iter()
                .map(|item| (item.key.clone(), item.slot, item.container, item.quantity))
                .collect::<Vec<_>>(),
        )
    };
    set_current_player_hp(&mut session, 0);

    let buy_packets = session.handle_packet(ClientPacket::BuyItem {
        item_index,
        count: 2,
        panel_type: 0,
    });
    let resources = session.app.world().resource::<InventoryResource>();

    assert!(buy_packets.is_empty());
    assert_eq!(
        session.app.world().resource::<PlayerRuntimeResource>().gold,
        state_before.0
    );
    assert_eq!(
        resources
            .inventory_items
            .iter()
            .map(|item| (item.key.clone(), item.slot, item.container, item.quantity))
            .collect::<Vec<_>>(),
        state_before.1
    );
}

#[test]
fn crystal_npc_buy_item_invalid_contexts_are_silent_and_preserve_state() {
    let mut session = SimulationSession::new(wicked_trader_config());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let _ = session.interact(4990);
    let buy_sell_packets = session.select_npc_dialog_target("@BuySell");
    let ServerPacket::NPCGoods { list, .. } = &buy_sell_packets[0] else {
        panic!("first buy/sell packet should be NPCGoods");
    };
    let hp_drug = list
        .iter()
        .find(|item| item.item_index == 658 && item.count == 1)
        .expect("Wicked Trader should sell one-count HP drug");
    let item_index = hp_drug.unique_id;
    let state_before = {
        let inventory = session.app.world().resource::<InventoryResource>();
        let player = session.app.world().resource::<PlayerRuntimeResource>();
        (
            player.gold,
            inventory
                .inventory_items
                .iter()
                .map(|item| (item.key.clone(), item.slot, item.container, item.quantity))
                .collect::<Vec<_>>(),
        )
    };

    let bad_panel_packets = session.handle_packet(ClientPacket::BuyItem {
        item_index,
        count: 1,
        panel_type: 2,
    });
    let zero_count_packets = session.handle_packet(ClientPacket::BuyItem {
        item_index,
        count: 0,
        panel_type: 0,
    });
    let oversized_count_packets = session.handle_packet(ClientPacket::BuyItem {
        item_index,
        count: u16::MAX,
        panel_type: 0,
    });

    let _ = session.interact(4990);
    let _ = session.select_npc_dialog_target("@Repair");
    let repair_service_packets = session.handle_packet(ClientPacket::BuyItem {
        item_index,
        count: 1,
        panel_type: 0,
    });
    let resources = session.app.world().resource::<InventoryResource>();

    assert!(bad_panel_packets.is_empty());
    assert!(zero_count_packets.is_empty());
    assert!(oversized_count_packets.is_empty());
    assert!(repair_service_packets.is_empty());
    assert_eq!(
        session.app.world().resource::<PlayerRuntimeResource>().gold,
        state_before.0
    );
    assert_eq!(
        resources
            .inventory_items
            .iter()
            .map(|item| (item.key.clone(), item.slot, item.container, item.quantity))
            .collect::<Vec<_>>(),
        state_before.1
    );
}

