#[test]
fn crystal_npc_dialog_target_runs_followup_section_and_can_return_main() {
    let mut config = SimulationConfig::default();
    config.visible_npcs.push(crate::VisibleNpcRecord {
        object_id: 4997,
        name: "Village Board".to_string(),
        image: 5,
        colour_argb: -1,
        position: Point { x: 331, y: 270 },
        direction: MirDirection::Left,
        quest_ids: Vec::new(),
        script_key: Some("BichonProvince/BichonWall/Board".to_string()),
    });
    let mut session = SimulationSession::new(config);
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let _ = session.interact(4997);
    let next_packets = session.select_npc_dialog_target("@main-1");
    let next_snapshot = session.world_snapshot();
    let next_dialog = next_snapshot
        .active_npc_dialog
        .as_ref()
        .expect("next dialog should be active");

    assert!(next_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectChat {
            object_id: 4997,
            ..
        }
    )));
    assert!(next_dialog
        .links
        .iter()
        .any(|link| link.text.contains("Weapon shop")));
    assert!(next_dialog
        .links
        .iter()
        .any(|link| link.text.contains("Book store")));
    assert!(next_dialog
        .links
        .iter()
        .any(|link| link.target.eq_ignore_ascii_case("@go-weap")));
    assert!(next_dialog
        .links
        .iter()
        .any(|link| link.target.eq_ignore_ascii_case("@Exit")));

    let _ = session.interact(4997);
    let _ = session.select_npc_dialog_target("@ask");
    let ask_snapshot = session.world_snapshot();
    let ask_dialog = ask_snapshot
        .active_npc_dialog
        .as_ref()
        .expect("ask dialog should be active");

    assert!(ask_dialog
        .body
        .iter()
        .any(|line| line.contains("Travelling Merchant Damian")));
    assert!(ask_dialog
        .links
        .iter()
        .any(|link| link.target.eq_ignore_ascii_case("@Main")));

    let _ = session.select_npc_dialog_target("@Main");
    let main_snapshot = session.world_snapshot();
    let main_dialog = main_snapshot
        .active_npc_dialog
        .as_ref()
        .expect("main dialog should be active");

    assert!(main_dialog
        .links
        .iter()
        .any(|link| link.target.eq_ignore_ascii_case("@main-1")));

    let _ = session.select_npc_dialog_target("@Exit");
    assert!(session.world_snapshot().active_npc_dialog.is_none());
}

