#[test]
fn crystal_npc_time_and_bag_conditions_follow_runtime_state() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let now = crystal_local_time_snapshot().expect("local time snapshot should be available");
    let bag_slots = crystal_npc_free_bag_slots(session.app.world());

    assert!(evaluate_crystal_npc_condition(
        session.app.world_mut(),
        &format!("DAYOFWEEK {}", now.day_of_week)
    ));
    assert!(evaluate_crystal_npc_condition(
        session.app.world_mut(),
        &format!("HOUR {}", now.hour)
    ));
    assert!(evaluate_crystal_npc_condition(
        session.app.world_mut(),
        &format!("MIN {}", now.minute)
    ));
    assert!(evaluate_crystal_npc_condition(
        session.app.world_mut(),
        &format!("HASBAGSPACE >= {}", bag_slots)
    ));
    assert!(!evaluate_crystal_npc_condition(
        session.app.world_mut(),
        &format!("HASBAGSPACE > {}", bag_slots)
    ));
    assert!(evaluate_crystal_npc_condition(
        session.app.world_mut(),
        "GROUPLEADER"
    ));
    assert!(evaluate_crystal_npc_condition(
        session.app.world_mut(),
        "GROUPCOUNT = 1"
    ));
}

