#[test]
fn crystal_npc_savevalue_and_loadvalue_persist_across_reload() {
    let temp_dir =
        std::env::temp_dir().join(format!("mir2-npc-values-test-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&temp_dir);
    std::fs::create_dir_all(&temp_dir).expect("tempdir");
    let store_path = temp_dir.join("accounts.json");

    let config = SimulationConfig::default().with_account_store_path(store_path.clone());
    let mut first = SimulationSession::new(config);
    first.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let mut packets = Vec::new();

    assert_eq!(
        execute_crystal_npc_action_line(
            first.app.world_mut(),
            r#"SAVEVALUE "quests\flags.txt" profile answer "Scout""#,
            &mut packets,
            &mut CrystalNpcExecutionState::default(),
        ),
        CrystalNpcActionControl::Continue
    );
    first.save_active_character();

    let reloaded_config = SimulationConfig::default().with_account_store_path(store_path);
    let mut second = SimulationSession::new(reloaded_config);
    second.handle_packet(ClientPacket::StartGame { character_index: 0 });

    assert_eq!(
        execute_crystal_npc_action_line(
            second.app.world_mut(),
            r#"LOADVALUE A1 "quests\flags.txt" profile answer"#,
            &mut packets,
            &mut CrystalNpcExecutionState::default(),
        ),
        CrystalNpcActionControl::Continue
    );

    assert_eq!(
        super::crystal_npc_variable_value(second.app.world(), "A1").as_deref(),
        Some("Scout")
    );

    let _ = std::fs::remove_dir_all(temp_dir);
}

#[test]
fn crystal_npc_monclear_marks_current_map_monsters_dead() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let mut packets = Vec::new();

    let alive_before = session
        .world_snapshot()
        .entities
        .iter()
        .filter(|entity| entity.kind == crate::WorldEntityKind::Monster && !entity.dead)
        .count();
    assert!(alive_before > 0);

    assert_eq!(
        execute_crystal_npc_action_line(
            session.app.world_mut(),
            "MONCLEAR 0",
            &mut packets,
            &mut CrystalNpcExecutionState::default(),
        ),
        CrystalNpcActionControl::Continue
    );

    let alive_after = session
        .world_snapshot()
        .entities
        .iter()
        .filter(|entity| entity.kind == crate::WorldEntityKind::Monster && !entity.dead)
        .count();
    assert_eq!(alive_after, 0);
    assert!(packets.is_empty());
}

#[test]
fn crystal_npc_giveskill_maps_runtime_and_crystal_manifest_entries() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    {
        let mut resources = session.app.world_mut().resource_mut::<SkillResource>();
        resources
            .skills
            .retain(|skill| skill.key != "minor-heal" && skill.key != "magicshield");
    }
    let mut packets = Vec::new();

    assert_eq!(
        execute_crystal_npc_action_line(
            session.app.world_mut(),
            "GIVESKILL Healing 3",
            &mut packets,
            &mut CrystalNpcExecutionState::default(),
        ),
        CrystalNpcActionControl::Continue
    );
    assert_eq!(
        execute_crystal_npc_action_line(
            session.app.world_mut(),
            "GIVESKILL MagicShield 2",
            &mut packets,
            &mut CrystalNpcExecutionState::default(),
        ),
        CrystalNpcActionControl::Continue
    );

    let snapshot = session.world_snapshot();
    assert!(snapshot
        .known_skills
        .iter()
        .any(|skill| skill.key == "minor-heal"));
    assert!(snapshot
        .known_skills
        .iter()
        .any(|skill| skill.key == "magicshield"));
    let runtime_skill = session
        .app
        .world()
        .resource::<SkillResource>()
        .skills
        .iter()
        .find(|skill| skill.key == "minor-heal")
        .expect("healing should map to runtime skill");
    let manifest_skill = session
        .app
        .world()
        .resource::<SkillResource>()
        .skills
        .iter()
        .find(|skill| skill.key == "magicshield")
        .expect("magic shield should be recorded from crystal manifest");
    assert_eq!(runtime_skill.level, 3);
    assert_eq!(manifest_skill.level, 2);
    assert!(packets.is_empty());
}

#[test]
fn defeating_field_wasp_advances_and_turns_in_quest() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_player_position(&mut session, Point { x: 326, y: 270 });
    let _ = session.interact(4001);

    kill_field_wasp(&mut session);
    let after_kill = session.world_snapshot();
    assert_eq!(after_kill.quest_log[0].stage, QuestStage::ReadyToTurnIn);
    assert!(after_kill.inventory_items.iter().any(|item| {
        item.container == ItemContainer::Quest && item.key == "quest-wasp-stinger"
    }));

    set_player_position(&mut session, Point { x: 326, y: 270 });
    let _ = session.interact(4001);
    let after_turn_in = session.world_snapshot();

    assert_eq!(after_turn_in.quest_log[0].stage, QuestStage::Completed);
    assert_eq!(after_turn_in.gold, 1580);
    assert!(after_turn_in
        .equipment_items
        .iter()
        .any(|item| { item.slot == EquipmentSlot::RingRight && item.name == "Guide Ring" }));
    assert!(after_turn_in.inventory_items.iter().any(|item| {
        item.container == ItemContainer::Bag1 && item.key == "repair-powder" && item.quantity == 2
    }));
    assert!(!after_turn_in
        .inventory_items
        .iter()
        .any(|item| item.key == "quest-wasp-stinger"));
}

#[test]
fn quest_turn_in_full_bag_preserves_quest_state_and_rewards() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    fill_all_bag_slots(&mut session);
    {
        let mut resources = session.app.world_mut().resource_mut::<QuestResource>();
        let quest = resources.quests.first_mut().expect("starter quest");
        quest.stage = QuestStage::ReadyToTurnIn;
        quest.current = quest.required;
    }
    {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        resources.inventory_items.push(ItemState {
            key: "quest-wasp-stinger".to_string(),
            name: "Wasp Stinger".to_string(),
            icon: super::item_icon_for_key("quest-wasp-stinger"),
            slot: 0,
            unique_id: 0,
            container: ItemContainer::Quest,
            quantity: 1,
            description: "Quest turn-in full-bag regression item.".to_string(),
            durability_current: None,
            durability_max: None,
            weight: 0,
            equip_slot: None,
            grade: ItemGrade::None,
            added_attack: 0,
            added_defence: 0,
            added_stats: Vec::new(),
            cursed: false,
            socket_slots: 0,
            gem_count: 0,
            identified: None,
            soul_bound_id: None,
            sealed_expiry_time_binary_datetime: 0,
            sealed_next_time_binary_datetime: 0,
            rental_binding_flags: 0,
            attack: 0,
            defence: 0,
            heal_hp: 0,
            heal_mp: 0,
        });
    }
    let before = session.world_snapshot();

    set_player_position(&mut session, Point { x: 326, y: 270 });
    let _ = session.interact(4001);
    let after = session.world_snapshot();

    assert_eq!(after.free_bag_slots, 0);
    assert_eq!(after.gold, before.gold);
    assert_eq!(after.quest_log[0].stage, QuestStage::ReadyToTurnIn);
    assert!(after
        .inventory_items
        .iter()
        .any(|item| item.key == "quest-wasp-stinger"));
    assert!(!after
        .inventory_items
        .iter()
        .any(|item| item.key == "repair-powder"));
    assert!(!after
        .equipment_items
        .iter()
        .any(|item| item.slot == EquipmentSlot::RingRight && item.name == "Guide Ring"));
}

