fn crystal_test_drop_entry(
    raw_line: &str,
    chance_raw: &str,
    item_name: &str,
    amount: Option<u32>,
    group: Option<mir2_game_data::CrystalDropGroup>,
) -> mir2_game_data::CrystalDropEntry {
    mir2_game_data::CrystalDropEntry {
        raw_line: raw_line.to_string(),
        chance_raw: chance_raw.to_string(),
        chance_numerator: None,
        chance_denominator: None,
        item_name: item_name.to_string(),
        amount,
        modifiers: Vec::new(),
        group,
    }
}

fn crystal_test_item_drop(item_name: &str) -> mir2_game_data::CrystalDropEntry {
    crystal_test_drop_entry(&format!("0 {item_name}"), "0", item_name, Some(1), None)
}

fn crystal_test_gold_drop(amount: u32) -> mir2_game_data::CrystalDropEntry {
    crystal_test_drop_entry(&format!("0 Gold {amount}"), "0", "Gold", Some(amount), None)
}

fn crystal_test_group_drop(
    raw_line: &str,
    random: bool,
    first: bool,
    entries: Vec<mir2_game_data::CrystalDropEntry>,
) -> mir2_game_data::CrystalDropEntry {
    crystal_test_drop_entry(
        raw_line,
        "0",
        "GROUP",
        None,
        Some(mir2_game_data::CrystalDropGroup {
            random,
            first,
            entries,
        }),
    )
}

fn resolved_item_names(drops: &[super::ResolvedDropTemplate]) -> Vec<String> {
    drops
        .iter()
        .filter_map(|drop| match drop {
            super::ResolvedDropTemplate::Item { name, .. } => Some(name.clone()),
            super::ResolvedDropTemplate::Gold { .. } => None,
        })
        .collect()
}

#[test]
fn crystal_group_random_keeps_gold_and_selects_one_successful_item() {
    let entry = crystal_test_group_drop(
        "0 GROUP*",
        true,
        false,
        vec![
            crystal_test_gold_drop(1_000),
            crystal_test_item_drop("(HP)DrugSmall"),
            crystal_test_item_drop("(MP)DrugSmall"),
        ],
    );

    let drops =
        super::crystal_attempt_drop_entry(&entry, 0, 91, 0).expect("group parent should pass");
    let gold = drops
        .iter()
        .filter_map(|drop| match drop {
            super::ResolvedDropTemplate::Gold { amount, .. } => Some(*amount),
            super::ResolvedDropTemplate::Item { .. } => None,
        })
        .collect::<Vec<_>>();
    let item_names = resolved_item_names(&drops);

    assert_eq!(gold.len(), 1, "GROUP* should keep successful child gold");
    assert!((500..1500).contains(&gold[0]));
    assert_eq!(item_names.len(), 1, "GROUP* should choose one item");
    assert!(item_names[0] == "(HP)DrugSmall" || item_names[0] == "(MP)DrugSmall");
}

#[test]
fn crystal_group_first_stops_after_first_successful_child() {
    let entry = crystal_test_group_drop(
        "0 GROUP^",
        false,
        true,
        vec![
            crystal_test_item_drop("(HP)DrugSmall"),
            crystal_test_item_drop("(MP)DrugSmall"),
        ],
    );

    let drops =
        super::crystal_attempt_drop_entry(&entry, 0, 92, 0).expect("group parent should pass");

    assert_eq!(resolved_item_names(&drops), vec!["(HP)DrugSmall"]);
}

#[test]
fn crystal_nested_group_combines_recursive_random_and_outer_first_rules() {
    let nested_random = crystal_test_group_drop(
        "0 GROUP*",
        true,
        false,
        vec![
            crystal_test_item_drop("(HP)DrugSmall"),
            crystal_test_item_drop("(MP)DrugSmall"),
        ],
    );
    let outer_first = crystal_test_group_drop(
        "0 GROUP^",
        false,
        true,
        vec![nested_random, crystal_test_item_drop("SpiritBlade")],
    );

    let drops = super::crystal_attempt_drop_entry(&outer_first, 0, 93, 0)
        .expect("outer group parent should pass");
    let item_names = resolved_item_names(&drops);

    assert_eq!(item_names.len(), 1);
    assert!(item_names[0] == "(HP)DrugSmall" || item_names[0] == "(MP)DrugSmall");
}

