#[test]
fn pickup_preserves_random_added_stats_in_gained_item_payload() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_player_position(&mut session, Point { x: 330, y: 270 });

    super::spawn_ground_drop(
        session.app.world_mut(),
        Point { x: 330, y: 270 },
        "",
        None,
        super::DropLoot::InventoryItem {
            key: "spiritblade".to_string(),
            name: "SpiritBlade".to_string(),
            description: "Random stat pickup test item.".to_string(),
            weight: 10,
            durability_current: Some(20_000),
            durability_max: Some(21_000),
            added_attack: 2,
            added_defence: 1,
            added_stats: vec![super::UserItemStat {
                stat: super::CRYSTAL_STAT_MAX_MC,
                value: 3,
            }],
            cursed: true,
            socket_slots: 2,
            show_group_pickup: false,
        },
        1,
        "SpiritBlade".to_string(),
    );
    let packets = session.handle_packet(ClientPacket::PickUp);
    let snapshot = session.world_snapshot();

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::GainedItem { item }
            if item.cursed
                && item.slots.len() == 2
                && item.added_stats.iter().any(|stat| {
                    stat.stat == super::CRYSTAL_STAT_MAX_DC && stat.value == 2
                })
                && item.added_stats.iter().any(|stat| {
                    stat.stat == super::CRYSTAL_STAT_MAX_AC && stat.value == 1
                })
                && item.added_stats.iter().any(|stat| {
                    stat.stat == super::CRYSTAL_STAT_MAX_MC && stat.value == 3
                })
    )));
    assert!(snapshot.inventory_items.iter().any(|item| {
        item.key == "spiritblade" && item.added_attack == 2 && item.added_defence == 1
    }));
    let resources = session.app.world().resource::<InventoryResource>();
    let item = resources
        .inventory_items
        .iter()
        .find(|item| item.key == "spiritblade")
        .expect("picked random stat item should be in inventory state");
    assert!(item.cursed);
    assert_eq!(item.socket_slots, 2);
    assert!(item
        .added_stats
        .iter()
        .any(|stat| { stat.stat == super::CRYSTAL_STAT_MAX_MC && stat.value == 3 }));
}

