#[test]
fn drop_gold_packet_emits_lose_gold() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let player_position = player_position(&session);

    let packets = session.handle_packet(ClientPacket::DropGold { amount: 100 });
    let snapshot = session.world_snapshot();

    assert_eq!(snapshot.gold, 1180);
    let gold_location = packets
        .iter()
        .find_map(|packet| match packet {
            ServerPacket::ObjectGold { info } if info.gold == 100 => Some(info.location.clone()),
            _ => None,
        })
        .expect("drop gold packet");
    assert_ne!(gold_location, player_position);
    assert!(super::tile_distance(&gold_location, &player_position) <= 5);
    assert!(packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoseGold { gold: 100 })));
}

