#[test]
fn crystal_drop_search_respects_drop_stack_size_limit() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_player_position(&mut session, Point { x: 340, y: 270 });
    let origin = Point { x: 330, y: 270 };

    for index in 0..super::CRYSTAL_DROP_STACK_SIZE {
        super::spawn_ground_drop(
            session.app.world_mut(),
            origin.clone(),
            "",
            None,
            super::DropLoot::Gold(1),
            1,
            format!("Stack Blocker {index}"),
        );
    }

    let placed = super::drop_ground_drop(
        session.app.world_mut(),
        origin.clone(),
        1,
        "",
        None,
        super::DropLoot::Gold(1),
        1,
        "Overflow Gold".to_string(),
    )
    .expect("overflow drop should find a nearby tile");
    let snapshot = session.world_snapshot();

    assert_ne!(placed.position, origin);
    assert_eq!(super::tile_distance(&placed.position, &origin), 1);
    assert_eq!(
        snapshot
            .ground_drops
            .iter()
            .filter(|drop| drop.x == origin.x && drop.y == origin.y)
            .count(),
        super::CRYSTAL_DROP_STACK_SIZE
    );
    assert!(snapshot.ground_drops.iter().any(|drop| {
        drop.object_id == placed.object_id
            && drop.x == placed.position.x
            && drop.y == placed.position.y
    }));
}

#[test]
fn crystal_drop_search_skips_map_transfer_source_tiles() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let movement_source = Point { x: 340, y: 270 };
    assert!(super::is_current_map_transfer_source(
        session.app.world(),
        &movement_source
    ));

    let placed = super::drop_ground_drop(
        session.app.world_mut(),
        movement_source.clone(),
        2,
        "",
        None,
        super::DropLoot::Gold(1),
        1,
        "Transfer Skip Gold".to_string(),
    )
    .expect("drop should move off the transfer source");

    assert_ne!(placed.position, movement_source);
    assert!(!super::is_current_map_transfer_source(
        session.app.world(),
        &placed.position
    ));
    assert!(super::tile_distance(&placed.position, &movement_source) <= 2);
}

#[test]
fn dropped_inventory_item_can_be_removed_from_bag_and_spawned_on_ground() {
    let mut session = SimulationSession::new(SimulationConfig::default());

    let before_start_packets = session.drop_item("red-potion");
    assert!(before_start_packets.is_empty());

    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let before = session.world_snapshot();
    let player_position = player_position(&session);
    assert!(before
        .inventory_items
        .iter()
        .any(|item| item.key == "red-potion"));

    let packets = session.drop_item("red-potion");
    let after = session.world_snapshot();

    assert!(!after
        .inventory_items
        .iter()
        .any(|item| item.key == "red-potion"));
    assert!(after
        .ground_drops
        .iter()
        .any(|drop| drop.name.contains("Potion")));
    assert!(after.ground_drops.iter().any(|drop| {
        drop.name.contains("Potion")
            && (Point {
                x: drop.x,
                y: drop.y,
            }) != player_position
            && super::tile_distance(
                &Point {
                    x: drop.x,
                    y: drop.y,
                },
                &player_position,
            ) <= 1
    }));
    assert!(packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::ObjectItem { .. })));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::DropItem {
            unique_id: 0,
            count: 5,
            hero_inventory: false,
            success: true
        }
    )));
    assert!(!packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::Chat { .. })));

    let missing_packets = session.drop_item("missing-red-potion");
    assert!(missing_packets.is_empty());
}

