#[test]
fn sell_item_service_context_requires_live_npc_object() {
    let mut session = SimulationSession::new(wicked_trader_config());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let _ = session.interact(4990);
    let _ = session.select_npc_dialog_target("@BuySell");
    let state_before = {
        let resources = session.app.world().resource::<InventoryResource>();
        let npc = session.app.world().resource::<NpcStateResource>();
        (
            player_gold(&session),
            resources
                .inventory_items
                .iter()
                .map(|item| (item.key.clone(), item.slot, item.container, item.quantity))
                .collect::<Vec<_>>(),
            npc.npc_buy_back_items.clone(),
        )
    };

    let trader_npc =
        super::entity_by_object_id(session.app.world(), 4_990).expect("trader npc should exist");
    let _ = session.app.world_mut().despawn(trader_npc);
    sync_visible_objects(&mut session);

    let packets = session.handle_packet(ClientPacket::SellItem {
        unique_id: 4,
        count: 1,
    });
    let resources = session.app.world().resource::<InventoryResource>();

    assert_eq!(
        packets,
        vec![ServerPacket::SellItem {
            unique_id: 4,
            count: 1,
            success: false,
        }]
    );
    assert_eq!(player_gold(&session), state_before.0);
    assert_eq!(
        resources
            .inventory_items
            .iter()
            .map(|item| (item.key.clone(), item.slot, item.container, item.quantity))
            .collect::<Vec<_>>(),
        state_before.1
    );
    assert_eq!(
        session
            .app
            .world()
            .resource::<NpcStateResource>()
            .npc_buy_back_items,
        state_before.2
    );
}

