#[test]
fn ground_drop_expires_after_crystal_item_timeout() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_player_position(&mut session, Point { x: 330, y: 270 });
    let current_tick = runtime_tick(session.app.world());

    super::spawn_ground_drop(
        session.app.world_mut(),
        Point { x: 330, y: 270 },
        "",
        None,
        super::DropLoot::InventoryItem {
            key: "bronze-helmet".to_string(),
            name: "Bronze Helmet".to_string(),
            description: "Ground drop expiry test item.".to_string(),
            weight: 4,
            durability_current: None,
            durability_max: None,
            added_attack: 0,
            added_defence: 0,
            added_stats: Vec::new(),
            cursed: false,
            socket_slots: 0,
            show_group_pickup: false,
        },
        1,
        "Bronze Helmet".to_string(),
    );
    let drop_object_id = session
        .app
        .world()
        .resource::<ObjectIdAllocatorResource>()
        .next_drop_object_id
        .saturating_sub(1);
    let drop_entity = super::entity_by_object_id(session.app.world(), drop_object_id)
        .expect("drop entity should exist");
    assert_eq!(
        session
            .app
            .world()
            .entity(drop_entity)
            .get::<super::DropExpiry>()
            .expect("drop expiry")
            .expires_at_tick,
        current_tick + super::CRYSTAL_DROP_EXPIRE_TICKS
    );

    let _ = session.tick();
    let tick = runtime_tick(session.app.world());
    session
        .app
        .world_mut()
        .entity_mut(drop_entity)
        .insert(super::DropExpiry {
            expires_at_tick: tick,
        });

    let packets = session.tick();

    assert!(!session
        .world_snapshot()
        .ground_drops
        .iter()
        .any(|drop| drop.object_id == drop_object_id));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectRemove { object_id } if *object_id == drop_object_id
    )));
}

