#[test]
fn pickup_respects_crystal_drop_owner_window() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_player_position(&mut session, Point { x: 330, y: 270 });
    let current_tick = runtime_tick(session.app.world());

    super::spawn_ground_drop_with_ownership(
        session.app.world_mut(),
        Point { x: 330, y: 270 },
        "OmaFighter",
        None,
        super::DropLoot::InventoryItem {
            key: "bronze-helmet".to_string(),
            name: "Bronze Helmet".to_string(),
            description: "Owned pickup test item.".to_string(),
            weight: 4,
            durability_current: None,
            durability_max: None,
            added_attack: 0,
            added_defence: 0,
            added_stats: Vec::new(),
            cursed: false,
            socket_slots: 0,
            show_group_pickup: false,
        },
        1,
        "Bronze Helmet".to_string(),
        Some(super::DropOwnership {
            owner_object_id: 9001,
            expires_at_tick: current_tick + super::CRYSTAL_DROP_OWNER_WINDOW_TICKS,
        }),
    );
    let drop_object_id = session
        .app
        .world()
        .resource::<ObjectIdAllocatorResource>()
        .next_drop_object_id
        .saturating_sub(1);
    assert!(session
        .world_snapshot()
        .ground_drops
        .iter()
        .any(|drop| drop.object_id == drop_object_id));

    let blocked_packets = session.handle_packet(ClientPacket::PickUp);
    assert!(blocked_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            chat_type: ChatType::System,
            message
        } if message
            == &super::localized_text_or_fallback(
                super::LanguageCode::English,
                "server.CannotPickupNotOwner",
                "server.CannotPickupNotOwner",
            )
    )));
    assert!(session
        .world_snapshot()
        .ground_drops
        .iter()
        .any(|drop| drop.object_id == drop_object_id));

    for _ in 0..=super::CRYSTAL_DROP_OWNER_WINDOW_TICKS {
        let _ = session.tick();
    }

    let pickup_packets = session.handle_packet(ClientPacket::PickUp);
    assert!(pickup_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::GainedItem { .. })));
    assert!(!session
        .world_snapshot()
        .ground_drops
        .iter()
        .any(|drop| drop.object_id == drop_object_id));
}

