#[test]
fn request_item_info_packet_returns_crystal_item_info() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let packets = session.handle_packet(ClientPacket::RequestItemInfo { item_index: 658 });

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::NewItemInfo { info }
            if info.index == 658
                && info.name == "(HP)DrugSmall"
                && info.stack_size == 20
                && info.stats.iter().any(|stat| stat.stat == 12 && stat.value == 30)
    )));

    let missing_packets = session.handle_packet(ClientPacket::RequestItemInfo { item_index: -1 });
    assert!(missing_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            message,
            chat_type: ChatType::System,
        } if message
            == &super::localized_text_or_fallback(
                super::LanguageCode::English,
                "server.NotFound",
                "server.NotFound",
            )
    )));
}

