#[test]
fn add_or_increment_item_respects_crystal_stack_size() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        resources.inventory_items.clear();
        resources.belt_items.clear();
    }

    let gained = super::add_or_increment_item(
        session.app.world_mut(),
        ItemContainer::Bag1,
        "red-potion",
        "Red Potion",
        "Crystal stack-size test potion.",
        0,
        25,
        1,
    );
    assert_eq!(gained.quantity, 5);

    let mut quantities = session
        .world_snapshot()
        .belt_items
        .iter()
        .filter(|item| item.key == "red-potion")
        .map(|item| item.quantity)
        .collect::<Vec<_>>();
    quantities.sort_unstable();
    assert_eq!(quantities, vec![5, 20]);

    let gained = super::add_or_increment_item(
        session.app.world_mut(),
        ItemContainer::Bag1,
        "red-potion",
        "Red Potion",
        "Crystal stack-size test potion.",
        0,
        17,
        1,
    );
    assert_eq!(gained.quantity, 2);

    let mut quantities = session
        .world_snapshot()
        .belt_items
        .iter()
        .filter(|item| item.key == "red-potion")
        .map(|item| item.quantity)
        .collect::<Vec<_>>();
    quantities.sort_unstable();
    assert_eq!(quantities, vec![2, 20, 20]);
}

