#[test]
fn item_roll_fields_persist_through_save_and_reload() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    let packets = session.handle_packet(ClientPacket::Login {
        account_id: "roll-save".to_string(),
        password: "demo".to_string(),
    });
    assert!(packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoginSuccess { .. })));
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_active_character_class_gender_level(&mut session, MirClass::Warrior, MirGender::Male, 10);
    let _ = session.use_item("bronze-helmet");
    add_inventory_crystal_item(&mut session, "MysteryHelmet", 31);

    {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        let weapon = resources
            .equipment_items
            .iter_mut()
            .find(|item| item.slot == EquipmentSlot::Weapon)
            .expect("weapon");
        weapon.grade = ItemGrade::Rare;
        weapon.added_attack = 5;
        weapon.added_stats.push(super::UserItemStat {
            stat: super::CRYSTAL_STAT_MAX_MC,
            value: 4,
        });
        weapon.cursed = true;
        weapon.socket_slots = 2;

        let potion = resources
            .inventory_items
            .iter_mut()
            .find(|item| item.key == "red-potion")
            .expect("seed potion");
        potion.added_stats.push(super::UserItemStat {
            stat: super::CRYSTAL_STAT_ACCURACY,
            value: 2,
        });
        potion.cursed = true;
        potion.socket_slots = 1;

        let mystery_helmet = resources
            .inventory_items
            .iter_mut()
            .find(|item| item.slot == 31)
            .expect("mystery helmet");
        mystery_helmet.identified = Some(true);
        mystery_helmet.soul_bound_id = Some(77);
    }

    session.save_active_character();

    let mut reloaded_config = SimulationConfig::default();
    reloaded_config.account_store = session
        .app
        .world()
        .resource::<RuntimeConfigResource>()
        .config
        .account_store
        .clone();
    let mut reloaded = SimulationSession::new(reloaded_config);
    let login_packets = reloaded.handle_packet(ClientPacket::Login {
        account_id: "roll-save".to_string(),
        password: "demo".to_string(),
    });
    assert!(login_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoginSuccess { .. })));
    reloaded.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let snapshot = reloaded.world_snapshot();
    assert_eq!(
        snapshot
            .equipment_items
            .iter()
            .find(|item| item.slot == EquipmentSlot::Weapon)
            .map(|item| (item.grade, item.added_attack, item.attack)),
        Some((ItemGrade::Rare, 5, 9))
    );
    assert_eq!(
        snapshot
            .equipment_items
            .iter()
            .find(|item| item.slot == EquipmentSlot::Helmet)
            .map(|item| (item.grade, item.added_defence, item.defence)),
        Some((ItemGrade::Common, 1, 3))
    );
    let resources = reloaded.app.world().resource::<InventoryResource>();
    let weapon = resources
        .equipment_items
        .iter()
        .find(|item| item.slot == EquipmentSlot::Weapon)
        .expect("reloaded weapon");
    assert!(weapon.cursed);
    assert_eq!(weapon.socket_slots, 2);
    assert!(weapon
        .added_stats
        .iter()
        .any(|stat| { stat.stat == super::CRYSTAL_STAT_MAX_MC && stat.value == 4 }));

    let potion = resources
        .inventory_items
        .iter()
        .find(|item| item.key == "red-potion")
        .expect("reloaded potion");
    assert!(potion.cursed);
    assert_eq!(potion.socket_slots, 1);
    assert!(potion
        .added_stats
        .iter()
        .any(|stat| { stat.stat == super::CRYSTAL_STAT_ACCURACY && stat.value == 2 }));
    let mystery_helmet = resources
        .inventory_items
        .iter()
        .find(|item| item.slot == 31)
        .expect("reloaded mystery helmet");
    assert_eq!(mystery_helmet.identified, Some(true));
    assert_eq!(mystery_helmet.soul_bound_id, Some(77));
}

#[test]
fn storing_item_moves_bag_item_into_storage_snapshot() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    activate_storage_service(&mut session);

    let bag_item = session
        .world_snapshot()
        .inventory_items
        .into_iter()
        .find(|item| matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2))
        .expect("bag item");

    let packets = session.handle_packet(ClientPacket::StoreItem {
        from: i32::from(bag_item.slot),
        to: 4,
    });
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::StoreItem {
            from,
            to: 4,
            success: true
        } if *from == i32::from(bag_item.slot)
    )));
    assert!(packets
        .iter()
        .all(|packet| !matches!(packet, ServerPacket::Chat { .. })));

    let snapshot = session.world_snapshot();
    assert!(!snapshot
        .inventory_items
        .iter()
        .any(|item| item.key == bag_item.key && item.slot == bag_item.slot));
    assert!(snapshot
        .storage_items
        .iter()
        .any(|item| item.key == bag_item.key
            && item.slot == 4
            && item.container == ItemContainer::Storage));
}

