#[test]
fn repair_item_packet_repairs_inventory_unique_id_with_cost_and_max_dura_loss() {
    let mut session = SimulationSession::new(wicked_trader_config());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let template =
        super::crystal_item_template_for_item_key("wooden-sword").expect("wooden sword template");
    let max_dura = template.durability;
    let current_dura = max_dura / 2;
    add_repairable_inventory_item(
        &mut session,
        "wooden-sword",
        "Wooden Sword",
        30,
        current_dura,
        max_dura,
    );
    {
        let mut resources = session
            .app
            .world_mut()
            .resource_mut::<PlayerRuntimeResource>();
        resources.gold = 50_000;
    }
    let item_before = session
        .app
        .world()
        .resource::<InventoryResource>()
        .inventory_items
        .iter()
        .find(|item| item.slot == 30)
        .expect("repair item")
        .clone();
    let expected_cost = super::crystal_npc_repair_cost(&item_before, &template, 2.0, false);
    let expected_max = max_dura - ((max_dura - current_dura) / 30);

    let _ = session.interact(4990);
    let _ = session.select_npc_dialog_target("@Repair");
    let packets = session.handle_packet(ClientPacket::RepairItem { unique_id: 30 });
    let resources = session.app.world().resource::<InventoryResource>();
    let item = resources
        .inventory_items
        .iter()
        .find(|item| item.slot == 30)
        .expect("repaired item should remain");

    assert!(packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::RepairItem { unique_id: 30 })));
    assert!(packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoseGold { gold } if *gold == expected_cost)));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ItemRepaired {
            unique_id: 30,
            max_dura: packet_max,
            current_dura: packet_current
        } if *packet_max == expected_max && *packet_current == expected_max
    )));
    assert_eq!(player_gold(&session), 50_000 - expected_cost);
    assert_eq!(
        (item.durability_current, item.durability_max),
        (Some(expected_max), Some(expected_max))
    );
}

#[test]
fn repair_item_packet_uses_unique_id_when_it_differs_from_slot() {
    let mut session = SimulationSession::new(wicked_trader_config());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let template =
        super::crystal_item_template_for_item_key("wooden-sword").expect("wooden sword template");
    let max_dura = template.durability;
    let current_dura = max_dura / 2;
    add_repairable_inventory_item(
        &mut session,
        "wooden-sword",
        "Wooden Sword",
        30,
        current_dura,
        max_dura,
    );
    set_player_gold(&mut session, 50_000);
    let (repair_unique_id, expected_cost, expected_max) = {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        let item = resources
            .inventory_items
            .iter_mut()
            .find(|item| item.slot == 30)
            .expect("repair item");
        item.unique_id = 9_030;
        let expected_cost = super::crystal_npc_repair_cost(&item.clone(), &template, 2.0, false);
        let expected_max = max_dura - ((max_dura - current_dura) / 30);
        (item.unique_id, expected_cost, expected_max)
    };

    let _ = session.interact(4990);
    let _ = session.select_npc_dialog_target("@Repair");
    let packets = session.handle_packet(ClientPacket::RepairItem {
        unique_id: repair_unique_id,
    });
    let resources = session.app.world().resource::<InventoryResource>();
    let item = resources
        .inventory_items
        .iter()
        .find(|item| item.unique_id == repair_unique_id)
        .expect("repaired item should remain");

    assert!(packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::RepairItem { unique_id: 9_030 })));
    assert!(packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoseGold { gold } if *gold == expected_cost)));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ItemRepaired {
            unique_id: 9_030,
            max_dura,
            current_dura
        } if *max_dura == expected_max && *current_dura == expected_max
    )));
    assert_eq!(
        (item.durability_current, item.durability_max),
        (Some(expected_max), Some(expected_max))
    );
}

#[test]
fn repair_item_rejection_edges_follow_crystal_order() {
    let mut session = SimulationSession::new(wicked_trader_config());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let weapon_template =
        super::crystal_item_template_for_item_key("wooden-sword").expect("wooden sword template");
    let weapon_max = weapon_template.durability;
    let weapon_current = weapon_max / 2;
    add_repairable_inventory_item(
        &mut session,
        "wooden-sword",
        "Wooden Sword",
        30,
        weapon_current,
        weapon_max,
    );
    let item_before = session
        .app
        .world()
        .resource::<InventoryResource>()
        .inventory_items
        .iter()
        .find(|item| item.slot == 30)
        .expect("repair item")
        .clone();
    let expected_cost = super::crystal_npc_repair_cost(&item_before, &weapon_template, 2.0, false);
    assert!(expected_cost > 0);

    let _ = session.interact(4990);
    let _ = session.select_npc_dialog_target("@Repair");
    {
        let mut resources = session
            .app
            .world_mut()
            .resource_mut::<PlayerRuntimeResource>();
        resources.gold = expected_cost - 1;
    }
    let insufficient_gold_packets =
        session.handle_packet(ClientPacket::RepairItem { unique_id: 30 });
    let resources = session.app.world().resource::<InventoryResource>();
    let item = resources
        .inventory_items
        .iter()
        .find(|item| item.slot == 30)
        .expect("repair item should remain");
    assert!(insufficient_gold_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::RepairItem { unique_id: 30 })));
    assert!(!insufficient_gold_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoseGold { .. })));
    assert!(!insufficient_gold_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::ItemRepaired { .. })));
    assert_eq!(player_gold(&session), expected_cost - 1);
    assert_eq!(
        (item.durability_current, item.durability_max),
        (Some(weapon_current), Some(weapon_max))
    );

    add_repairable_inventory_item(&mut session, "red-potion", "Red Potion", 31, 0, 0);
    {
        let mut resources = session
            .app
            .world_mut()
            .resource_mut::<PlayerRuntimeResource>();
        resources.gold = 50_000;
    }
    let wrong_type_packets = session.handle_packet(ClientPacket::RepairItem { unique_id: 31 });
    assert!(wrong_type_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::RepairItem { unique_id: 31 })));
    assert!(wrong_type_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message.contains("cannot Repair this item here")
            || message.contains("CannotRepairItemHere")
    )));
    assert!(!wrong_type_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::ItemRepaired { .. })));

    let dont_repair_template =
        super::crystal_item_by_index(578).expect("DemonMask template should exist");
    let dont_repair_key = super::crystal_item_key_for_template(&dont_repair_template);
    add_repairable_inventory_item(
        &mut session,
        &dont_repair_key,
        &dont_repair_template.name,
        32,
        dont_repair_template.durability / 2,
        dont_repair_template.durability,
    );
    let dont_repair_packets = session.handle_packet(ClientPacket::RepairItem { unique_id: 32 });
    assert!(dont_repair_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::RepairItem { unique_id: 32 })));
    assert!(dont_repair_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message.contains("cannot Repair this item.")
            || message.contains("CannotRepairItem")
    )));
    assert!(!dont_repair_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::ItemRepaired { .. })));
}

