#[test]
fn casting_skill_applies_buff_and_cooldown() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let packets = session.cast_skill("battle-focus");
    let snapshot = session.world_snapshot();

    assert!(!packets.iter().any(
        |packet| matches!(packet, ServerPacket::Chat { message, .. } if message.contains("Cast"))
    ));
    assert!(snapshot
        .active_buffs
        .iter()
        .any(|buff| buff.key == "battle-focus"));
    assert!(snapshot
        .known_skills
        .iter()
        .find(|skill| skill.key == "battle-focus")
        .map(|skill| skill.cooldown_remaining_ticks > 0)
        .unwrap_or(false));
}

