#[test]
fn hostile_monster_prefers_stone_trap_over_other_friendly_summon_targets() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let origin = Point { x: 930, y: 930 };
    set_player_position(&mut session, origin.clone());
    let player_object_id = current_player_object_id(session.app.world()).expect("player object id");
    let current_tick = runtime_tick(session.app.world());
    let trap_template = crystal_dynamic_monster_template("StoneTrap").expect("stone trap template");
    let hostile = session
        .app
        .world_mut()
        .spawn((
            WorldObject,
            Monster,
            ObjectId(98_940_u32),
            DisplayName::literal("Trap Target Wasp"),
            Position(Point {
                x: origin.x + 3,
                y: origin.y,
            }),
            Facing(MirDirection::Left),
            MonsterAgent {
                image: 43,
                dead: false,
                patrol_origin: Point {
                    x: origin.x + 3,
                    y: origin.y,
                },
                ai: 0,
                disposition: WorldEntityDisposition::Hostile,
                hostile_to_player: true,
                tracking_player: true,
                view_range: 7,
                can_wander: false,
                move_interval_ticks: 1,
                attack_interval_ticks: 1,
                next_move_tick: current_tick,
                next_attack_tick: current_tick,
                route: Vec::new(),
                route_index: 0,
                route_waiting: false,
                next_route_tick: current_tick,
            },
            MonsterVitals { hp: 40, max_hp: 40 },
        ))
        .id();

    let toad = session
        .app
        .world_mut()
        .spawn((
            WorldObject,
            Monster,
            ObjectId(98_941_u32),
            DisplayName::literal("Friendly Dummy Summon"),
            Position(Point {
                x: origin.x + 1,
                y: origin.y + 1,
            }),
            Facing(MirDirection::Right),
            MonsterAgent {
                image: 61,
                dead: false,
                patrol_origin: Point {
                    x: origin.x + 1,
                    y: origin.y + 1,
                },
                ai: 61,
                disposition: WorldEntityDisposition::Friendly,
                hostile_to_player: false,
                tracking_player: false,
                view_range: 7,
                can_wander: false,
                move_interval_ticks: 1,
                attack_interval_ticks: 10,
                next_move_tick: current_tick,
                next_attack_tick: current_tick,
                route: Vec::new(),
                route_index: 0,
                route_waiting: false,
                next_route_tick: current_tick,
            },
            MonsterVitals { hp: 20, max_hp: 20 },
            SummonedMonster {
                summoner_object_id: player_object_id,
                visible_extra: true,
                expire_tick: None,
                require_summoner_within: Some(15),
                despawn_tick_after_death: None,
                totem_master_object_id: None,
                max_minions: Some(1),
            },
        ))
        .id();
    let trap = session
        .app
        .world_mut()
        .spawn((
            WorldObject,
            Monster,
            ObjectId(98_943_u32),
            DisplayName::literal("StoneTrap"),
            Position(Point {
                x: origin.x + 2,
                y: origin.y,
            }),
            Facing(MirDirection::Up),
            MonsterAgent {
                image: trap_template.monster_image,
                dead: false,
                patrol_origin: Point {
                    x: origin.x + 2,
                    y: origin.y,
                },
                ai: trap_template.monster_ai,
                disposition: WorldEntityDisposition::Friendly,
                hostile_to_player: false,
                tracking_player: false,
                view_range: i32::from(trap_template.monster_view_range),
                can_wander: false,
                move_interval_ticks: super::crystal_speed_to_ticks(
                    trap_template.monster_move_speed,
                ),
                attack_interval_ticks: super::crystal_speed_to_ticks(
                    trap_template.monster_attack_speed,
                ),
                next_move_tick: current_tick,
                next_attack_tick: current_tick,
                route: Vec::new(),
                route_index: 0,
                route_waiting: false,
                next_route_tick: current_tick,
            },
            MonsterVitals {
                hp: trap_template.monster_hp.max(1),
                max_hp: trap_template.monster_hp.max(1),
            },
            SummonedMonster {
                summoner_object_id: player_object_id,
                visible_extra: true,
                expire_tick: Some(current_tick + combat_delay_ticks(10_000)),
                require_summoner_within: Some(15),
                despawn_tick_after_death: None,
                totem_master_object_id: None,
                max_minions: Some(1),
            },
        ))
        .id();
    sync_visible_objects(&mut session);

    #[allow(deprecated)]
    let monster_entities: Vec<Entity> = session
        .app
        .world()
        .iter_entities()
        .filter_map(|entity| entity.get::<Monster>().map(|_| entity.id()))
        .collect();
    let hostile_position = entity_position(session.app.world(), hostile).expect("hostile position");
    let hostile_agent = session
        .app
        .world()
        .entity(hostile)
        .get::<MonsterAgent>()
        .expect("hostile agent");
    let trap_object_id = entity_object_id(session.app.world(), trap).expect("stone trap object id");
    let toad_object_id =
        entity_object_id(session.app.world(), toad).expect("spitting toad object id");
    let chosen_target = super::hostile_monster_summon_target(
        session.app.world(),
        &monster_entities,
        hostile,
        &hostile_position,
        hostile_agent,
    )
    .expect("hostile summon target");
    assert_eq!(chosen_target, trap);

    let packets = session.tick();
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectAttack { info } if info.object_id == 98_940_u32
    )));
    assert!(!packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectStruck { info }
            if info.object_id == toad_object_id && info.attacker_id == 98_940_u32
    )));
    let _ = trap_object_id;
}

#[test]
fn stonetrap_ignores_incoming_damage_and_keeps_full_health() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let origin = Point { x: 333, y: 267 };
    set_player_position(&mut session, origin.clone());
    let player = player_entity(session.app.world()).expect("player");
    session
        .app
        .world_mut()
        .entity_mut(player)
        .insert(PlayerVitals {
            hp: 120,
            max_hp: 120,
            mp: 200,
        });

    let _ = session.cast_skill("stonetrap");
    let _ = session.tick();
    let trap = find_monster_entity_by(&session, |name, _, _| name == "StoneTrap");
    set_entity_position(
        &mut session,
        trap,
        Point {
            x: origin.x + 1,
            y: origin.y,
        },
    );
    sync_visible_objects(&mut session);

    let trap_object_id = entity_object_id(session.app.world(), trap).expect("stone trap object id");
    let current_tick = runtime_tick(session.app.world());
    let player_object_id = current_player_object_id(session.app.world()).expect("player object id");
    super::schedule_damage_to_monster(
        session.app.world_mut(),
        current_tick,
        player_object_id,
        trap,
        99,
        Some("StoneTrap".to_string()),
        None,
    );

    let packets = session.tick();
    let trap_vitals = session
        .app
        .world()
        .entity(trap)
        .get::<MonsterVitals>()
        .expect("stone trap vitals");

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectStruck { info }
            if info.object_id == trap_object_id && info.attacker_id == player_object_id
    )));
    assert!(!packet_has_object_health(&packets, trap_object_id));
    assert_eq!(trap_vitals.hp, trap_vitals.max_hp);
    assert!(
        !session
            .app
            .world()
            .entity(trap)
            .get::<MonsterAgent>()
            .expect("stone trap agent")
            .dead
    );
}

