#[test]
fn stage5_shop_and_auction_full_bag_preserve_gold_and_items() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let full_bag_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.YouCannotCarryAnymore",
        "server.YouCannotCarryAnymore",
    );
    session
        .app
        .world_mut()
        .resource_mut::<PlayerRuntimeResource>()
        .credit = 10;
    fill_all_bag_slots(&mut session);
    let starting_gold = session.world_snapshot().gold;
    let starting_credit = session.world_snapshot().credit;

    let shop_packets = session.stage5_command(
        "shop.buy",
        vec!["full-bag-shop".to_string(), "25".to_string()],
    );
    let after_shop = session.world_snapshot();
    assert!(shop_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &full_bag_message
    )));
    assert_eq!(after_shop.free_bag_slots, 0);
    assert_eq!(after_shop.gold, starting_gold);
    assert!(!after_shop
        .inventory_items
        .iter()
        .any(|item| item.key == "full-bag-shop"));

    let credit_packets = session.stage5_command(
        "shop.buyCredit",
        vec!["full-bag-credit-shop".to_string(), "5".to_string()],
    );
    let after_credit_shop = session.world_snapshot();
    assert_eq!(after_credit_shop.free_bag_slots, 0);
    assert_eq!(after_credit_shop.credit, starting_credit - 5);
    assert!(credit_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoseCredit { credit: 5 })));
    assert!(after_credit_shop
        .stage5_systems
        .mail
        .iter()
        .any(|mail| mail.from == "Gameshop"
            && mail.items == vec!["full-bag-credit-shop".to_string()]
            && !mail.claimed));
    assert!(!after_credit_shop
        .inventory_items
        .iter()
        .any(|item| item.key == "full-bag-credit-shop"));
    let claim_packets = session.stage5_command("mail.claim", vec!["1".to_string()]);
    let after_full_bag_claim = session.world_snapshot();
    assert!(claim_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &full_bag_message
    )));
    assert!(after_full_bag_claim
        .stage5_systems
        .mail
        .iter()
        .any(|mail| mail.id == 1 && !mail.claimed));
    assert!(!after_full_bag_claim
        .inventory_items
        .iter()
        .any(|item| item.key == "full-bag-credit-shop"));

    session.stage5_command(
        "auction.list",
        vec!["full-bag-auction".to_string(), "50".to_string()],
    );
    let auction_packets = session.stage5_command("auction.buy", vec!["1".to_string()]);
    let after_auction = session.world_snapshot();
    assert!(auction_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &full_bag_message
    )));
    assert_eq!(after_auction.gold, starting_gold);
    assert!(!after_auction
        .inventory_items
        .iter()
        .any(|item| item.key == "full-bag-auction"));
    assert!(after_auction
        .stage5_systems
        .auction
        .iter()
        .any(|listing| listing.id == 1 && !listing.sold && !listing.cancelled));

    session
        .app
        .world_mut()
        .resource_mut::<Stage5SystemsResource>()
        .stage5_systems
        .profession
        .ore = 1;
    let craft_packets = session.stage5_command("craft", vec!["full-bag-craft".to_string()]);
    let after_craft = session.world_snapshot();
    assert!(craft_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &full_bag_message
    )));
    assert_eq!(after_craft.stage5_systems.profession.ore, 1);
    assert!(!after_craft
        .inventory_items
        .iter()
        .any(|item| item.key == "full-bag-craft"));
}

#[test]
fn stage5_trade_disconnect_before_accept_preserves_gold() {
    let temp_dir = unique_runtime_temp_dir("stage5-trade-disconnect");
    let store_path = temp_dir.join("accounts.json");
    let config = SimulationConfig::default().with_account_store_path(store_path.clone());
    let mut session = SimulationSession::new(config);
    session.handle_packet(ClientPacket::Login {
        account_id: "stage5-trade-disconnect".to_string(),
        password: "demo".to_string(),
    });
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let starting_gold = session.world_snapshot().gold;

    session.stage5_command("trade.start", vec!["Trader".to_string()]);
    session.stage5_command("trade.offerGold", vec!["75".to_string()]);
    session.save_active_character();

    let mut reloaded =
        SimulationSession::new(SimulationConfig::default().with_account_store_path(store_path));
    reloaded.handle_packet(ClientPacket::Login {
        account_id: "stage5-trade-disconnect".to_string(),
        password: "demo".to_string(),
    });
    reloaded.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let after_reload = reloaded.world_snapshot();
    assert_eq!(after_reload.gold, starting_gold);
    assert!(after_reload
        .stage5_systems
        .trade
        .as_ref()
        .is_some_and(|trade| !trade.accepted && !trade.completed && trade.offered_gold == 75));

    reloaded.stage5_command("trade.accept", Vec::new());
    let after_accept = reloaded.world_snapshot();
    assert_eq!(after_accept.gold, starting_gold - 75);
}

