#[test]
fn stage5_item_seal_emits_item_seal_changed() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let packets = session.stage5_command("item.seal", vec!["weapon".to_string(), "30".to_string()]);
    let expiry = packets.iter().find_map(|packet| match packet {
        ServerPacket::ItemSealChanged {
            unique_id,
            expiry_date_binary_datetime,
        } => {
            assert_eq!(*unique_id, 0);
            Some(*expiry_date_binary_datetime)
        }
        _ => None,
    });
    let expiry = expiry.expect("seal packet should be emitted");
    let snapshot = session.world_snapshot();

    assert_ne!(expiry, 0);
    assert!(snapshot.equipment_items.iter().any(|item| {
        item.slot == EquipmentSlot::Weapon
            && item.name == "Wooden Sword"
            && item.sealed_expiry_time_binary_datetime == expiry
    }));
}

#[test]
fn stage5_item_seal_sets_next_seal_delay_metadata() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let packets = session.stage5_command("item.seal", vec!["weapon".to_string(), "30".to_string()]);
    let expiry = packets.iter().find_map(|packet| match packet {
        ServerPacket::ItemSealChanged {
            expiry_date_binary_datetime,
            ..
        } => Some(*expiry_date_binary_datetime),
        _ => None,
    });
    let expiry = expiry.expect("seal packet should be emitted");
    let snapshot = session.world_snapshot();
    let weapon = snapshot
        .equipment_items
        .iter()
        .find(|item| item.slot == EquipmentSlot::Weapon)
        .expect("sealed weapon should be present");
    const TICKS_PER_MINUTE: i64 = 60 * 10_000_000;
    let expected_delay_ticks = i64::try_from(super::CRYSTAL_ITEM_SEAL_DELAY_MINUTES)
        .expect("seal delay fits i64")
        * TICKS_PER_MINUTE;

    assert_eq!(weapon.sealed_expiry_time_binary_datetime, expiry);
    assert_eq!(
        super::binary_datetime_ticks(weapon.sealed_next_time_binary_datetime),
        super::binary_datetime_ticks(expiry) + expected_delay_ticks
    );
}

#[test]
fn stage5_item_seal_rejects_already_sealed_equipment() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let first = session.stage5_command("item.seal", vec!["weapon".to_string(), "30".to_string()]);
    let expiry = first.iter().find_map(|packet| match packet {
        ServerPacket::ItemSealChanged {
            expiry_date_binary_datetime,
            ..
        } => Some(*expiry_date_binary_datetime),
        _ => None,
    });
    let expiry = expiry.expect("first seal should emit expiry");

    let second = session.stage5_command("item.seal", vec!["weapon".to_string(), "60".to_string()]);
    let snapshot = session.world_snapshot();

    assert!(!second
        .iter()
        .any(|packet| matches!(packet, ServerPacket::ItemSealChanged { .. })));
    assert!(second.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            chat_type: ChatType::System,
            message
        } if message
            == &super::localized_text_or_fallback(
                super::LanguageCode::English,
                "server.ItemAlreadySealed",
                "server.ItemAlreadySealed",
            )
    )));
    assert_eq!(
        snapshot
            .equipment_items
            .iter()
            .find(|item| item.slot == EquipmentSlot::Weapon)
            .map(|item| item.sealed_expiry_time_binary_datetime),
        Some(expiry)
    );
}

#[test]
fn stage5_item_seal_rejects_before_next_seal_date_after_expiry() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let next_seal = super::future_binary_datetime_minutes(30);
    {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        let weapon = resources
            .equipment_items
            .iter_mut()
            .find(|item| item.slot == EquipmentSlot::Weapon)
            .expect("weapon should be equipped");
        weapon.sealed_expiry_time_binary_datetime = 1;
        weapon.sealed_next_time_binary_datetime = next_seal;
    }

    let packets = session.stage5_command("item.seal", vec!["weapon".to_string(), "30".to_string()]);
    let snapshot = session.world_snapshot();

    assert!(!packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::ItemSealChanged { .. })));
    let reseal_message = super::format_localized_text(
        super::LanguageCode::English,
        "server.ItemCannotBeResealedFor",
        ["30 minutes".to_string()],
    );
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &reseal_message
    )));
    assert!(snapshot.equipment_items.iter().any(|item| {
        item.slot == EquipmentSlot::Weapon
            && item.sealed_expiry_time_binary_datetime == 1
            && item.sealed_next_time_binary_datetime == next_seal
    }));
}

#[test]
fn stage5_item_seal_next_delay_persists_across_save_reload() {
    let temp_dir = unique_runtime_temp_dir("seal-next-delay");
    let store_path = temp_dir.join("accounts.json");
    let config = SimulationConfig::default().with_account_store_path(store_path);
    let mut first = SimulationSession::new(config.clone());
    let _ = first.handle_packet(ClientPacket::Login {
        account_id: "demo".to_string(),
        password: "demo".to_string(),
    });
    let _ = first.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let _ = first.stage5_command("item.seal", vec!["weapon".to_string(), "30".to_string()]);
    let saved_next_seal = first
        .world_snapshot()
        .equipment_items
        .iter()
        .find(|item| item.slot == EquipmentSlot::Weapon)
        .map(|item| item.sealed_next_time_binary_datetime)
        .expect("sealed weapon should be present");
    assert_ne!(saved_next_seal, 0);
    first.save_active_character();

    let mut second = SimulationSession::new(config);
    let _ = second.handle_packet(ClientPacket::Login {
        account_id: "demo".to_string(),
        password: "demo".to_string(),
    });
    let _ = second.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let restored_next_seal = second
        .world_snapshot()
        .equipment_items
        .iter()
        .find(|item| item.slot == EquipmentSlot::Weapon)
        .map(|item| item.sealed_next_time_binary_datetime)
        .expect("restored weapon should be present");

    assert_eq!(restored_next_seal, saved_next_seal);
    let _ = std::fs::remove_dir_all(temp_dir);
}

#[test]
fn equipment_state_legacy_seal_metadata_defaults_next_seal_date() {
    let mut equipment = super::seed_equipment_items();
    let weapon = equipment
        .iter_mut()
        .find(|item| item.slot == EquipmentSlot::Weapon)
        .expect("seed weapon should exist");
    weapon.sealed_expiry_time_binary_datetime = super::future_binary_datetime_minutes(30);
    weapon.sealed_next_time_binary_datetime = super::future_binary_datetime_minutes(90);
    let mut legacy_value = serde_json::to_value(weapon).expect("equipment should serialize");
    legacy_value
        .as_object_mut()
        .expect("equipment should serialize as an object")
        .remove("sealed_next_time_binary_datetime");

    let restored: super::EquipmentState =
        serde_json::from_value(legacy_value).expect("legacy equipment should deserialize");

    assert_ne!(restored.sealed_expiry_time_binary_datetime, 0);
    assert_eq!(restored.sealed_next_time_binary_datetime, 0);
}

#[test]
fn stage5_item_seal_rejects_without_source_item() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let packets = session.stage5_command(
        "item.seal",
        vec![
            "weapon".to_string(),
            "30".to_string(),
            "stage5-seal-source".to_string(),
        ],
    );
    let snapshot = session.world_snapshot();

    assert!(!packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::ItemSealChanged { .. })));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message
            == &super::localized_text_or_fallback(
                super::LanguageCode::English,
                "server.NotFound",
                "server.NotFound",
            )
    )));
    assert!(snapshot.equipment_items.iter().any(|item| {
        item.slot == EquipmentSlot::Weapon
            && item.name == "Wooden Sword"
            && item.sealed_expiry_time_binary_datetime == 0
    }));
}

#[test]
fn stage5_item_seal_rejects_without_equipped_item() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    session
        .app
        .world_mut()
        .resource_mut::<InventoryResource>()
        .equipment_items
        .retain(|item| item.slot != EquipmentSlot::Weapon);

    let packets = session.stage5_command("item.seal", vec!["weapon".to_string()]);
    let snapshot = session.world_snapshot();

    assert!(!packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::ItemSealChanged { .. })));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message
            == &super::localized_text_or_fallback(
                super::LanguageCode::English,
                "server.NotFound",
                "server.NotFound",
            )
    )));
    assert!(!snapshot
        .equipment_items
        .iter()
        .any(|item| item.slot == EquipmentSlot::Weapon));
}

#[test]
fn stage5_item_seal_rejects_wrong_source_item() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    add_inventory_test_item(&mut session, "crystal-item-739", "DurabilityGem", 31, 1);

    let packets = session.stage5_command(
        "item.seal",
        vec![
            "weapon".to_string(),
            "30".to_string(),
            "crystal-item-739".to_string(),
        ],
    );
    let snapshot = session.world_snapshot();

    assert!(!packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::ItemSealChanged { .. })));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message
            == &super::localized_text_or_fallback(
                super::LanguageCode::English,
                "server.InvalidCombination",
                "server.InvalidCombination",
            )
    )));
    assert!(snapshot.inventory_items.iter().any(|item| {
        item.key == "crystal-item-739" && item.name == "DurabilityGem" && item.quantity == 1
    }));
    assert!(snapshot.equipment_items.iter().any(|item| {
        item.slot == EquipmentSlot::Weapon
            && item.name == "Wooden Sword"
            && item.sealed_expiry_time_binary_datetime == 0
    }));
}

#[test]
fn stage5_item_seal_consumes_source_item_on_success() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    add_seal_source_test_item(&mut session, 31, 2);

    let packets = session.stage5_command(
        "item.seal",
        vec![
            "weapon".to_string(),
            "30".to_string(),
            "stage5-seal-source".to_string(),
        ],
    );
    let expiry = packets.iter().find_map(|packet| match packet {
        ServerPacket::ItemSealChanged {
            unique_id,
            expiry_date_binary_datetime,
        } => {
            assert_eq!(*unique_id, 0);
            Some(*expiry_date_binary_datetime)
        }
        _ => None,
    });
    let expiry = expiry.expect("seal packet should be emitted");
    let snapshot = session.world_snapshot();

    let seal_message = super::format_localized_text(
        super::LanguageCode::English,
        "server.ItemSealedFor",
        ["45 minutes".to_string()],
    );
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &seal_message
    )));
    assert!(snapshot
        .inventory_items
        .iter()
        .any(|item| { item.key == "stage5-seal-source" && item.quantity == 1 }));
    assert!(snapshot.equipment_items.iter().any(|item| {
        item.slot == EquipmentSlot::Weapon
            && item.name == "Wooden Sword"
            && item.sealed_expiry_time_binary_datetime == expiry
    }));
}

#[test]
fn stage5_conquest_event_hero_mining_and_crafting_flow() {
    let mut unstarted_session = SimulationSession::new(SimulationConfig::default());
    let not_found_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.NotFound",
        "server.NotFound",
    );
    let missing_player_packets =
        unstarted_session.stage5_command("event.spawn", vec!["BugBat".to_string()]);
    assert!(missing_player_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &not_found_message
    )));

    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let crafting_failed_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.CraftingAttemptFailed",
        "server.CraftingAttemptFailed",
    );

    session.stage5_command("guild.create", vec!["BichonGuard".to_string()]);
    session.stage5_command("conquest.start", vec!["Sabuk".to_string()]);
    session.stage5_command("conquest.owner", Vec::new());
    let missing_event_packets =
        session.stage5_command("event.spawn", vec!["MissingMonster".to_string()]);
    assert!(missing_event_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &not_found_message
    )));
    let event_packets =
        session.stage5_command("event.spawn", vec!["BugBat".to_string(), "1".to_string()]);
    assert!(!event_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::Chat { .. })));
    let missing_hero_packets = session.stage5_command("hero.behaviour", vec!["2".to_string()]);
    assert!(missing_hero_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &not_found_message
    )));
    session.stage5_command("hero.recruit", vec!["Aide".to_string()]);
    let hero_behaviour_packets = session.stage5_command("hero.behaviour", vec!["2".to_string()]);
    assert!(!hero_behaviour_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::Chat { .. })));
    let failed_craft_packets = session.stage5_command("craft", vec!["crafted-blade".to_string()]);
    assert!(failed_craft_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &crafting_failed_message
    )));
    assert!(!session
        .world_snapshot()
        .inventory_items
        .iter()
        .any(|item| item.key == "crafted-blade"));
    session.stage5_command("mine", vec!["3".to_string()]);
    session.stage5_command("craft", vec!["crafted-blade".to_string()]);

    let snapshot = session.world_snapshot();
    assert_eq!(snapshot.stage5_systems.conquest.castle_owner, "BichonGuard");
    assert_eq!(
        snapshot.stage5_systems.conquest.active_wars,
        vec!["Sabuk".to_string()]
    );
    assert!(snapshot
        .stage5_systems
        .conquest
        .event_log
        .iter()
        .any(|entry| entry.contains("Event spawned")));
    assert_eq!(
        snapshot
            .stage5_systems
            .hero
            .as_ref()
            .map(|hero| hero.name.as_str()),
        Some("Aide")
    );
    assert_eq!(
        snapshot
            .stage5_systems
            .hero
            .as_ref()
            .map(|hero| hero.behaviour),
        Some(2)
    );
    assert_eq!(snapshot.stage5_systems.profession.ore, 2);
    assert!(snapshot
        .stage5_systems
        .profession
        .crafted_items
        .contains(&"crafted-blade".to_string()));
    assert!(snapshot
        .inventory_items
        .iter()
        .any(|item| item.key == "crafted-blade"));
}
